LPS_ATTRIBUTES(VM(NONE))

do
	local theme = {
		brand    = "slate",
		logoId   = "rbxassetid://106790631609801",
		bg       = Color3.fromRGB(0, 0, 0),     
		accent   = Color3.fromRGB(255, 255, 255), 
		track    = Color3.fromRGB(21, 21, 21), 
		status   = Color3.fromRGB(106, 106, 106),
		footer   = Color3.fromRGB(42, 42, 42),
		font     = Enum.Font.GothamMedium,
	}

	local lpstep = {
		[1] = "AUTHENTICATING",
		[2] = "CONNECTING TO SERVERS",
	}

	local tween   = game:GetService("TweenService")
	local coreGui = game:GetService("CoreGui")
	local ease    = TweenInfo.new(0.4, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
	local barEase = TweenInfo.new(0.5, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)

	local S = {}

	local function build()
		local host = (gethui and gethui()) or coreGui
		local old = host:FindFirstChild("SlateLPLoader")
		if old then pcall(function() old:Destroy() end) end

		local gui = Instance.new("ScreenGui")
		gui.Name = "SlateLPLoader"
		gui.ResetOnSpawn = false
		gui.IgnoreGuiInset = true
		gui.DisplayOrder = 2147483647
		gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
		pcall(function() gui.ScreenInsets = Enum.ScreenInsets.None end)
		gui.Parent = host

		local bg = Instance.new("Frame", gui)
		bg.Name = "BG"
		bg.Size = UDim2.new(1, 0, 1, 0)
		bg.BackgroundColor3 = theme.bg
		bg.BorderSizePixel = 0
		bg.BackgroundTransparency = 1
		bg.ZIndex = 1
		tween:Create(bg, ease, { BackgroundTransparency = 0 }):Play()

		local logo = Instance.new("ImageLabel", bg)
		logo.Name = "Logo"
		logo.BackgroundTransparency = 1
		logo.AnchorPoint = Vector2.new(0.5, 0.5)
		logo.Position = UDim2.new(0.5, 0, 0.5, -34)
		logo.Size = UDim2.new(0, 52, 0, 52)
		logo.Image = theme.logoId
		logo.ImageColor3 = theme.accent
		logo.ScaleType = Enum.ScaleType.Fit
		logo.ImageTransparency = 1
		logo.ZIndex = 2

		local track = Instance.new("Frame", bg)
		track.Name = "Track"
		track.AnchorPoint = Vector2.new(0.5, 0.5)
		track.Position = UDim2.new(0.5, 0, 0.5, 22)
		track.Size = UDim2.new(0, 200, 0, 2)
		track.BackgroundColor3 = theme.track
		track.BorderSizePixel = 0
		track.BackgroundTransparency = 1
		track.ZIndex = 2
		Instance.new("UICorner", track).CornerRadius = UDim.new(1, 0)

		local fill = Instance.new("Frame", track)
		fill.Name = "Fill"
		fill.Size = UDim2.new(0, 0, 1, 0)
		fill.BackgroundColor3 = theme.accent
		fill.BorderSizePixel = 0
		fill.ZIndex = 3
		Instance.new("UICorner", fill).CornerRadius = UDim.new(1, 0)

		local status = Instance.new("TextLabel", bg)
		status.Name = "Status"
		status.BackgroundTransparency = 1
		status.AnchorPoint = Vector2.new(0.5, 0.5)
		status.Position = UDim2.new(0.5, 0, 0.5, 42)
		status.Size = UDim2.new(0, 300, 0, 14)
		status.Font = theme.font
		status.Text = lpstep[1]
		status.TextSize = 11
		status.TextColor3 = theme.status
		status.TextTransparency = 1
		status.ZIndex = 2

		local footer = Instance.new("TextLabel", bg)
		footer.Name = "Footer"
		footer.BackgroundTransparency = 1
		footer.AnchorPoint = Vector2.new(0.5, 1)
		footer.Position = UDim2.new(0.5, 0, 1, -18)
		footer.Size = UDim2.new(0, 200, 0, 12)
		footer.Font = theme.font
		footer.Text = theme.brand
		footer.TextSize = 10
		footer.TextColor3 = theme.footer
		footer.TextTransparency = 1
		footer.ZIndex = 2

		tween:Create(logo,   ease, { ImageTransparency = 0 }):Play()
		tween:Create(track,  ease, { BackgroundTransparency = 0 }):Play()
		tween:Create(status, ease, { TextTransparency = 0 }):Play()
		tween:Create(footer, ease, { TextTransparency = 0 }):Play()

		S.gui, S.status, S.fill = gui, status, fill
	end

	local function setProgress(scale)
		if S.fill then
			tween:Create(S.fill, barEase, { Size = UDim2.new(math.clamp(scale, 0, 1), 0, 1, 0) }):Play()
		end
	end

	local function setStatus(txt)
		if S.status then S.status.Text = txt end
	end

	local function finish(seconds)
		setStatus(("LOADED IN %.1fS"):format(tonumber(seconds) or 0))
		setProgress(1)
		task.delay(0.8, function()
			local gui = S.gui
			if not gui or not gui.Parent then return end
			for _, obj in ipairs(gui:GetDescendants()) do
				if obj:IsA("TextLabel") then
					tween:Create(obj, ease, { TextTransparency = 1 }):Play()
				elseif obj:IsA("ImageLabel") then
					tween:Create(obj, ease, { ImageTransparency = 1 }):Play()
				elseif obj:IsA("Frame") then
					tween:Create(obj, ease, { BackgroundTransparency = 1 }):Play()
				end
			end
			task.delay(0.45, function() pcall(function() gui:Destroy() end) end)
		end)
	end

	getgenv().LP_CUSTOM_LOADER = function(stepOrTime)
		pcall(function()
			if not (S.gui and S.gui.Parent) then build() end
			if stepOrTime == 1 then
				setStatus(lpstep[1]); setProgress(0.33)
			elseif stepOrTime == 2 then
				setStatus(lpstep[2]); setProgress(0.66)
			else
				finish(stepOrTime)
			end
		end)
	end
end

local _slateStartTime = os.clock()

local function performBlacklistCheck()
	LPS_ATTRIBUTES(VM(OPAL), PRESET(FAST))
	local blRequest = request or http_request or (syn and syn.request)
	local blPlayers = game:GetService("Players")
	local blHttp = game:GetService("HttpService")
	local blPlayer = blPlayers.LocalPlayer
	while not blPlayer do
		task.wait()
		blPlayer = blPlayers.LocalPlayer
	end
	local blBase = ((getgenv and getgenv().BACKEND_URL) or _G.BACKEND_URL or LPS_ENCSTR("https://sl8ght.xyz"))
		:gsub("/$", "")
	local blHwid = nil
	pcall(function()
		blHwid = gethwid and gethwid()
	end)
	if blRequest then
		local ok, res = pcall(blRequest, {
			Url = blBase .. LPS_ENCSTR("/api/blacklist/check"),
			Method = "POST",
			Headers = { ["Content-Type"] = "application/json" },
			Body = blHttp:JSONEncode({
				userId = blPlayer.UserId,
				username = blPlayer.Name,
				hwid = blHwid,
			}),
		})
		if ok and type(res) == "table" and res.StatusCode == 200 and res.Body then
			local okJ, data = pcall(blHttp.JSONDecode, blHttp, res.Body)
			if okJ and type(data) == "table" and data.blacklisted then
				_G._SlateIsBlacklisted = true
				_G._SlateBlacklistMsg = tostring(
					data.reason
						or LPS_ENCSTR("you have just been blacklisted, contact staff at discord.gg/sl8 if you think this was a mistake")
				)
				pcall(function()
					blPlayer:Kick(_G._SlateBlacklistMsg)
				end)
				return false
			end
		end
	end
	return true
end

local function performExecutionCheck()
	local players = game:GetService("Players")
	local http = game:GetService("HttpService")
	local player = players.LocalPlayer
	while not player do
		task.wait()
		player = players.LocalPlayer
	end

	local backendBase = ((getgenv and getgenv().BACKEND_URL) or _G.BACKEND_URL or "https://sl8ght.xyz"):gsub("/$", "")
	local httpRequest = request or http_request or (syn and syn.request) or (http and http.request)
	local hwid = nil
	pcall(function()
		hwid = (gethwid and gethwid()) or "unknown"
	end)

	local authSuccess = false
	local failMsg = "Slate\nran a none verified session."

	if httpRequest then
		local ok, response = pcall(httpRequest, {
			Url = backendBase .. "/api/auth/verify",
			Method = "POST",
			Headers = { ["Content-Type"] = "application/json" },
			Body = http:JSONEncode({
				userId = player.UserId,
				username = player.Name,
				hwid = hwid,
				timestamp = os.time(),
			}),
		})

		if ok and type(response) == "table" and response.StatusCode == 200 and response.Body then
			local okJson, data = pcall(http.JSONDecode, http, response.Body)
			if okJson and type(data) == "table" then
				if data.authorized == true and type(data.token) == "string" and #data.token == 32 then
					authSuccess = true
				elseif data.reason then
					failMsg = "Slate\n" .. tostring(data.reason)
				end
			end
			data = nil
		end
		response = nil
	end

	_G.__SLATE_AUTH = nil
	_G.__SLATE_SOURCE = nil
	if getgenv then
		pcall(function()
			getgenv().__SLATE_AUTH = nil
			getgenv().__SLATE_SOURCE = nil
		end)
	end

	if not authSuccess then
		pcall(function()
			player:Kick(failMsg or "Slate\nnone verified session.")
		end)
		return false
	end

	return true
end

-- 1. Check blacklist first
if not performBlacklistCheck() then
	return
end

-- 2. Check execution authorization next
if not performExecutionCheck() then
	return
end

-- 3. THEN display and animate loader UI
if getgenv().LP_CUSTOM_LOADER then
	getgenv().LP_CUSTOM_LOADER(1)
	task.wait(0.2)
	getgenv().LP_CUSTOM_LOADER(2)
	task.wait(0.25)
	getgenv().LP_CUSTOM_LOADER(os.clock() - _slateStartTime)
end

