-- Player row management
local playerRows = {}

local function highlightRows()
    for uid, row in pairs(playerRows) do
        local sel = State.selectedPlayer and uid == State.selectedPlayer.UserId
        TweenService:Create(row, TweenInfo.new(0.12), {
            BackgroundColor3 = sel and C.ROW_SELECTED or C.ROW_BG,
        }):Play()
        local nm = row:FindFirstChild("NL")
        if nm then
            nm.TextColor3 = sel and C.WHITE or C.TEXT
            nm.Font = sel and Enum.Font.GothamBold or Enum.Font.GothamMedium
        end
        local indicator = row:FindFirstChild("SelDot")
        if indicator then indicator.Visible = sel end
    end
end

local function selectPlayer(p)
    if p == plr then return end
    if State.copyActive then stopCopying() end
    State.selectedPlayer = p
    highlightRows()
    updateStatus()
end

local function makeRow(player)
    if player == plr then return end
    if playerRows[player.UserId] then return end

    local row = Instance.new("TextButton")
    row.Name = player.Name; row.Text = ""
    row.BackgroundColor3 = C.ROW_BG
    row.BorderSizePixel = 0
    row.Size = UDim2.new(1, 0, 0, 32)
    row.AutoButtonColor = false
    row.Parent = listFrame
    corner(row, 5)

    local thumb = Instance.new("ImageLabel")
    thumb.Name = "T"
    thumb.BackgroundColor3 = C.PANEL
    thumb.BorderSizePixel = 0
    thumb.AnchorPoint = Vector2.new(0, 0.5)
    thumb.Position = UDim2.new(0, 5, 0.5, 0)
    thumb.Size = UDim2.new(0, 22, 0, 22)
    thumb.Parent = row
    corner(thumb, 11)
    task.spawn(function()
        local ok, img = pcall(function()
            return Players:GetUserThumbnailAsync(
                player.UserId, Enum.ThumbnailType.HeadShot, Enum.ThumbnailSize.Size48x48)
        end)
        if ok then thumb.Image = img end
    end)

    local nameLbl = Instance.new("TextLabel"); nameLbl.Name = "NL"
    nameLbl.BackgroundTransparency = 1
    nameLbl.Position = UDim2.new(0, 32, 0, 3)
    nameLbl.Size = UDim2.new(1, -50, 0, 14)
    nameLbl.Font = Enum.Font.GothamMedium
    nameLbl.Text = player.DisplayName
    nameLbl.TextColor3 = C.TEXT
    nameLbl.TextSize = 11
    nameLbl.TextXAlignment = Enum.TextXAlignment.Left
    nameLbl.TextTruncate = Enum.TextTruncate.AtEnd
    nameLbl.Parent = row

    local userLbl = Instance.new("TextLabel")
    userLbl.BackgroundTransparency = 1
    userLbl.Position = UDim2.new(0, 32, 0, 17)
    userLbl.Size = UDim2.new(1, -50, 0, 12)
    userLbl.Font = Enum.Font.Gotham
    userLbl.Text = "@" .. player.Name
    userLbl.TextColor3 = C.DIM
    userLbl.TextSize = 9
    userLbl.TextXAlignment = Enum.TextXAlignment.Left
    userLbl.TextTruncate = Enum.TextTruncate.AtEnd
    userLbl.Parent = row

    local dot = Instance.new("Frame"); dot.Name = "SelDot"
    dot.AnchorPoint = Vector2.new(1, 0.5)
    dot.Position = UDim2.new(1, -8, 0.5, 0)
    dot.Size = UDim2.new(0, 6, 0, 6)
    dot.BackgroundColor3 = C.WHITE
    dot.BorderSizePixel = 0
    dot.Visible = false
    dot.Parent = row
    corner(dot, 3)

    row.MouseButton1Click:Connect(function() selectPlayer(player) end)
    row.MouseEnter:Connect(function()
        if State.selectedPlayer ~= player then
            TweenService:Create(row, TweenInfo.new(0.1), { BackgroundColor3 = C.PANEL_HOVER }):Play()
        end
    end)
    row.MouseLeave:Connect(function()
        if State.selectedPlayer ~= player then
            TweenService:Create(row, TweenInfo.new(0.1), { BackgroundColor3 = C.ROW_BG }):Play()
        end
    end)

    playerRows[player.UserId] = row

    local q = searchBox.Text:lower()
    if q ~= "" then
        local m = player.Name:lower():find(q, 1, true)
                or player.DisplayName:lower():find(q, 1, true)
        row.Visible = m ~= nil and m ~= false
    end
end

local function removeRow(player)
    local row = playerRows[player.UserId]
    if row then row:Destroy(); playerRows[player.UserId] = nil end
    if State.selectedPlayer == player then
        State.selectedPlayer = nil
        if State.copyActive then stopCopying() end
        updateStatus()
    end
end

local function rebuildList()
    for uid, row in pairs(playerRows) do row:Destroy(); playerRows[uid] = nil end
    for _, p in ipairs(Players:GetPlayers()) do task.spawn(makeRow, p) end
end

local function filterRows(q)
    q = q:lower()
    for uid, row in pairs(playerRows) do
        local p = Players:GetPlayerByUserId(uid)
        if p then
            local m = q == ""
                or p.Name:lower():find(q, 1, true)
                or p.DisplayName:lower():find(q, 1, true)
            row.Visible = m ~= nil and m ~= false
        end
    end
end

rebuildList()
Players.PlayerAdded:Connect(makeRow)
Players.PlayerRemoving:Connect(removeRow)
refreshBtn.MouseButton1Click:Connect(rebuildList)
searchBox:GetPropertyChangedSignal("Text"):Connect(function() filterRows(searchBox.Text) end)

