-- Slatelib Capsule Handle (Rest 35x20 -> Held 41x22)
local sliderThumb = Instance.new("Frame")
sliderThumb.BackgroundColor3 = Color3.fromRGB(245, 245, 245)
sliderThumb.BorderSizePixel = 0
sliderThumb.AnchorPoint = Vector2.new(0.5, 0.5)
sliderThumb.Size = UDim2.fromOffset(35, 20)
sliderThumb.Position = UDim2.new(0, 0, 0.5, 0)
sliderThumb.ZIndex = 5
sliderThumb.Parent = sliderTrack
corner(sliderThumb, 10)
local thumbStroke = addBorderStroke(sliderThumb, Color3.fromRGB(255, 255, 255), 1)
thumbStroke.Transparency = 0.8

local DIST_MIN, DIST_MAX = 1.0, 20.0
local function setDistFromAlpha(alpha, animate)
    alpha = math.clamp(alpha, 0, 1)
    State.copyDistance = DIST_MIN + alpha * (DIST_MAX - DIST_MIN)
    State.copyDistance = math.floor(State.copyDistance * 2 + 0.5) / 2
    State.copyDistance = math.clamp(State.copyDistance, DIST_MIN, DIST_MAX)
    local a = (State.copyDistance - DIST_MIN) / (DIST_MAX - DIST_MIN)
    
    local handleOffset = (1 - 2 * a) * (35 / 2 - 2)
    local targetPos = UDim2.new(a, handleOffset, 0.5, 0)
    local targetSize = UDim2.new(a, 0, 1, 0)
    
    if animate then
        local info = TweenInfo.new(0.3, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
        TweenService:Create(sliderFill, info, { Size = targetSize }):Play()
        TweenService:Create(sliderThumb, info, { Position = targetPos }):Play()
    else
        sliderFill.Size = targetSize
        sliderThumb.Position = targetPos
    end
    distValLbl.Text = string.format("%.1f st", State.copyDistance)
end
setDistFromAlpha((State.copyDistance - DIST_MIN) / (DIST_MAX - DIST_MIN), false)

local sliderDragging = false
local function sliderInputBegan(inp)
    if inp.UserInputType == Enum.UserInputType.MouseButton1
       or inp.UserInputType == Enum.UserInputType.Touch then
        sliderDragging = true
        TweenService:Create(sliderThumb, TweenInfo.new(0.2, Enum.EasingStyle.Exponential), {
            Size = UDim2.fromOffset(41, 22),
            BackgroundTransparency = 0.2
        }):Play()
        local rel = (inp.Position.X - sliderTrack.AbsolutePosition.X) / sliderTrack.AbsoluteSize.X
        setDistFromAlpha(rel, true)
    end
end
sliderTrack.InputBegan:Connect(sliderInputBegan)
sliderThumb.InputBegan:Connect(sliderInputBegan)

UserInputService.InputChanged:Connect(function(inp)
    if sliderDragging and
       (inp.UserInputType == Enum.UserInputType.MouseMovement
        or inp.UserInputType == Enum.UserInputType.Touch) then
        local rel = (inp.Position.X - sliderTrack.AbsolutePosition.X) / sliderTrack.AbsoluteSize.X
        setDistFromAlpha(rel, true)
    end
end)
UserInputService.InputEnded:Connect(function(inp)
    if inp.UserInputType == Enum.UserInputType.MouseButton1
       or inp.UserInputType == Enum.UserInputType.Touch then
        if sliderDragging then
            sliderDragging = false
            TweenService:Create(sliderThumb, TweenInfo.new(0.2, Enum.EasingStyle.Exponential), {
                Size = UDim2.fromOffset(35, 20),
                BackgroundTransparency = 0
            }):Play()
        end
    end
end)

