local function makeSideBtn(txt, xOffset)
    local b = Instance.new("TextButton")
    b.AnchorPoint = Vector2.new(1, 0.5)
    b.Position = UDim2.new(1, xOffset, 0.5, 0)
    b.Size = UDim2.new(0, 60, 0, 22)
    b.BackgroundColor3 = C.TOGGLE_OFF
    b.BorderSizePixel = 0
    b.Font = Enum.Font.GothamMedium
    b.Text = txt
    b.TextColor3 = C.KNOB_INACTIVE
    b.TextSize = 10
    b.AutoButtonColor = false
    b.Parent = sideRow
    corner(b, 4)
    return b
end
local rightBtn = makeSideBtn("Right", -12)
local leftBtn  = makeSideBtn("Left",  -78)

local function updateSide()
    TweenService:Create(leftBtn, TweenInfo.new(0.12), {
        BackgroundColor3 = State.copySide == -1 and C.WHITE or C.TOGGLE_OFF,
        TextColor3 = State.copySide == -1 and C.BG or C.KNOB_INACTIVE,
    }):Play()
    TweenService:Create(rightBtn, TweenInfo.new(0.12), {
        BackgroundColor3 = State.copySide == 1 and C.WHITE or C.TOGGLE_OFF,
        TextColor3 = State.copySide == 1 and C.BG or C.KNOB_INACTIVE,
    }):Play()
end
updateSide()
leftBtn.MouseButton1Click:Connect(function()  State.copySide = -1; updateSide() end)
rightBtn.MouseButton1Click:Connect(function() State.copySide =  1; updateSide() end)

