setCopyAnywhereVisuals = function()
    local info = TweenInfo.new(0.35, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out)
    if State.copyAnywhere then
        TweenService:Create(caTrack, info, {
            BackgroundColor3 = Color3.fromRGB(32, 32, 40)
        }):Play()
        TweenService:Create(caTrackStroke, info, {
            Color = Color3.fromRGB(80, 80, 95),
            Transparency = 0.2
        }):Play()
        TweenService:Create(copyAnywhereKnob, info, {
            Position = UDim2.new(1, -28, 0.5, 0),
            BackgroundColor3 = Color3.fromRGB(255, 255, 255),
            BackgroundTransparency = 0
        }):Play()
        TweenService:Create(knobStroke, info, {
            Color = Color3.fromRGB(255, 255, 255),
            Transparency = 0
        }):Play()
        
        distRow.BackgroundTransparency = 0.4
        sideRow.BackgroundTransparency = 0.4
        dLbl.TextColor3 = C.DIM
        distValLbl.TextColor3 = C.DIM
        sideLbl.TextColor3 = C.DIM
    else
        TweenService:Create(caTrack, info, {
            BackgroundColor3 = Color3.fromRGB(18, 18, 22)
        }):Play()
        TweenService:Create(caTrackStroke, info, {
            Color = Color3.fromRGB(42, 42, 48),
            Transparency = 0.4
        }):Play()
        TweenService:Create(copyAnywhereKnob, info, {
            Position = UDim2.new(0, 3, 0.5, 0),
            BackgroundColor3 = Color3.fromRGB(130, 130, 140),
            BackgroundTransparency = 0.6
        }):Play()
        TweenService:Create(knobStroke, info, {
            Color = Color3.fromRGB(255, 255, 255),
            Transparency = 0.7
        }):Play()
        
        distRow.BackgroundTransparency = 0
        sideRow.BackgroundTransparency = 0
        dLbl.TextColor3 = C.TEXT
        distValLbl.TextColor3 = C.WHITE
        sideLbl.TextColor3 = C.TEXT
    end
end

local function toggleCopyAnywhere()
    State.copyAnywhere = not State.copyAnywhere
    setCopyAnywhereVisuals()
    applyAnchorForMode()
    if State.copyActive then
        Notify(State.copyAnywhere and "Copy Anywhere: ON \u{2014} move freely" or "Copy Anywhere: OFF")
    end
end

caBtn.MouseButton1Click:Connect(toggleCopyAnywhere)

