local isMin = false
minBtn.MouseButton1Click:Connect(function()
    isMin = not isMin
    local ti = TweenInfo.new(0.25, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
    if isMin then
        body.Visible = false
        TweenService:Create(mainFrame, ti, { Size = UDim2.new(0, WIN_W, 0, HEAD_H) }):Play()
    else
        TweenService:Create(mainFrame, ti, { Size = UDim2.new(0, WIN_W, 0, WIN_H) }):Play()
        task.delay(0.23, function() body.Visible = true end)
    end
end)

