					end
					Humanoid:ChangeState(Enum.HumanoidStateType.Swimming)
					swimbeat = _IY_RunService.Heartbeat:Connect(function()
						pcall(function()
							_IY__IY_getRoot(_IY_lp.Character).AssemblyLinearVelocity = (
								(Humanoid.MoveDirection ~= Vector3.new() or _IY_UIS:IsKeyDown(Enum.KeyCode.Space))
									and _IY__IY_getRoot(_IY_lp.Character).AssemblyLinearVelocity
								or Vector3.new()
							)
						end)
					end)
					swimming = true
				end
