								_IY_getRoot(_IY_lp.Character),
								TweenInfo.new(_IY_tweenSpeed, Enum.EasingStyle.Linear),
								{ CFrame = _IY_getRoot(_IY_Players[v].Character).CFrame + Vector3.new(3, 1, 0) }
