		{
			name = "dupetools",
			desc = "Duplicate all tools in backpack",
			args = "<arg>",
			aliases = { "clonetools" },
			callback = function(arg)
				local args = _IY_splitArgs(arg)
				local speaker = _IY_lp
				local LOOP_NUM = tonumber(args[1]) or 1
				local OrigPos = _IY_lp.Character.Humanoid.RootPart.Position
				local Tools, TempPos = {}, Vector3.new(math.random(-2e5, 2e5), 2e5, math.random(-2e5, 2e5))
				for i = 1, LOOP_NUM do
					local Human = _IY_lp.Character:WaitForChild("Humanoid")
					wait(0.1, Human.Parent:MoveTo(TempPos))
					Human.RootPart.Anchored = _IY_lp:ClearCharacterAppearance(wait(0.1)) or true
					local t = GetHandleTools(_IY_lp)
					while #t > 0 do
						for _, v in ipairs(t) do
							task.spawn(function()
								for _ = 1, 25 do
									v.Parent = _IY_lp.Character
									v.Handle.Anchored = true
								end
								for _ = 1, 5 do
									v.Parent = workspace
								end
								table.insert(Tools, v.Handle)
							end)
						end
						t = GetHandleTools(_IY_lp)
					end
					wait(0.1)
					_IY_lp.Character = _IY_lp.Character:Destroy()
					_IY_lp.CharacterAdded
						:Wait()
						:WaitForChild("Humanoid").Parent
						:MoveTo(LOOP_NUM == i and OrigPos or TempPos, wait(0.1))
					if i == LOOP_NUM or i % 5 == 0 then
						local HRP = _IY_lp.Character.Humanoid.RootPart
						if type(firetouchinterest) == "function" then
							for _, v in ipairs(Tools) do
								firetouchinterest(v, HRP, 0)
								firetouchinterest(v, HRP, 1)
								v.Anchored = false
							end
						else
							for _, v in ipairs(Tools) do
								task.spawn(function()
									local x = v.CanCollide
									v.CanCollide = false
									v.Anchored = false
									for _ = 1, 10 do
										v.CFrame = HRP.CFrame
										wait()
									end
									v.CanCollide = x
								end)
							end
						end
						wait(0.1)
						Tools = {}
					end
					TempPos = TempPos + Vector3.new(10, math.random(-5, 5), 0)
				end
			end,
		},
		{
			name = "touchinterests",
			desc = "Fire touch events on parts",
			args = "<arg>",
			aliases = { "touchinterest", "firetouchinterests", "firetouchinterest" },
			callback = function(arg)
				local args = _IY_splitArgs(arg)
				local speaker = _IY_lp
				local Root = _IY_getRoot(_IY_lp.Character) or _IY_lp.Character:FindFirstChildWhichIsA("BasePart")
				if not firetouchinterest then
					_IY_notify(
						"Incompatible Exploit",
						"Your exploit does not support this command (missing firetouchinterest)"
					)
					return
				end

				local function Touch(x)
					x = x:FindFirstAncestorWhichIsA("Part") or x.Parent
					if x then
						return task.spawn(function()
							firetouchinterest(x, Root, 0)
							task.wait()
							firetouchinterest(x, Root, 1)
						end)
					end
					x.CFrame = Root.CFrame
				end
				if args[1] then
					local name = getstring(1, args):lower()
					print(name .. " -name")
					for _, v in ipairs(workspace:GetDescendants()) do
						if v:IsA("TouchTransmitter") and v.Name:lower() == name or v.Parent.Name:lower() == name then
							Touch(v)
						end
					end
				else
					for _, v in ipairs(workspace:GetDescendants()) do
						if v.IsA(v, "TouchTransmitter") then
							Touch(v)
						end
					end
				end
			end,
		},
