					end) and _IY_lp:GetMouse()
					local target = mouse and mouse.Target
					if target then
						local humanoid = target.Parent:FindFirstChildOfClass("Humanoid")
							or target.Parent.Parent:FindFirstChildOfClass("Humanoid")
						if humanoid then
							t = humanoid.Parent
						end
