					if not code then
						_IY_notify("Auto Key Press", "Invalid key")
						return
					end
					execCmd("unautokeypress")
					wait()
					local clickDelay = 0.1
					local releaseDelay = 0.1
					if args[2] and isNumber(args[2]) then
						clickDelay = args[2]
					end
					if args[3] and isNumber(args[3]) then
						releaseDelay = args[3]
					end
					autoKeyPressing = true
					cancelAutoKeyPress = _IY_UIS.InputBegan:Connect(function(input, gameProcessedEvent)
						if not gameProcessedEvent then
							if
								(input.KeyCode == Enum.KeyCode.Backspace and _IY_UIS:IsKeyDown(Enum.KeyCode.Equals))
								or (input.KeyCode == Enum.KeyCode.Equals and _IY_UIS:IsKeyDown(Enum.KeyCode.Backspace))
							then
								autoKeyPressing = false
								cancelAutoKeyPress:Disconnect()
							end
						end
					end)
					_IY_notify("Auto Key Press", "Press [backspace] and [=] at the same time to stop")
					repeat
						wait(clickDelay)
						keypress(code)
						wait(releaseDelay)
						keyrelease(code)
					until autoKeyPressing == false
					if cancelAutoKeyPress then
						cancelAutoKeyPress:Disconnect()
