		{
			name = "cframefly",
			desc = "CFrame-based fly mode",
			args = "<arg>",
			aliases = { "cfly" },
			callback = function(arg)
				local args = _IY_splitArgs(arg)
				local speaker = _IY_lp
				if args[1] and isNumber(args[1]) then
					CFspeed = args[1]
				end
				_IY_lp.Character:FindFirstChildOfClass("Humanoid").PlatformStand = true
				local Head = _IY_lp.Character:WaitForChild("Head")
				Head.Anchored = true
				if CFloop then
					CFloop:Disconnect()
				end
				CFloop = _IY_RunService.Heartbeat:Connect(function(deltaTime)
					local moveDirection = _IY_lp.Character:FindFirstChildOfClass("Humanoid").MoveDirection
						* (CFspeed * deltaTime)
					local headCFrame = Head.CFrame
					local camera = workspace.CurrentCamera
					local cameraCFrame = camera.CFrame
					local cameraOffset = headCFrame:ToObjectSpace(cameraCFrame).Position
					cameraCFrame = cameraCFrame * CFrame.new(-cameraOffset.X, -cameraOffset.Y, -cameraOffset.Z + 1)
					local cameraPosition = cameraCFrame.Position
					local headPosition = headCFrame.Position
					local objectSpaceVelocity =
						CFrame.new(cameraPosition, Vector3.new(headPosition.X, cameraPosition.Y, headPosition.Z))
							:VectorToObjectSpace(moveDirection)
					Head.CFrame = CFrame.new(headPosition)
						* (cameraCFrame - cameraPosition)
						* CFrame.new(objectSpaceVelocity)
				end)
			end,
		},
