		{
			name = "antifling",
			desc = "Enable anti-fling protection",
			callback = function(arg)
				local args = _IY_splitArgs(arg)
				local speaker = _IY_lp
				if antifling then
					antifling:Disconnect()
					antifling = nil
				end
				local partCache = setmetatable({}, { __mode = "k" })
				local dirty = setmetatable({}, { __mode = "k" })
				local watched = setmetatable({}, { __mode = "k" })
				antifling = _IY_RunService.Stepped:Connect(function()
					for _, player in ipairs(_IY_Players:GetPlayers()) do
						local char = player ~= _IY_lp and player.Character
						if char then
							if not watched[char] then
								watched[char] = true
								dirty[char] = true
								local function markDirty()
									dirty[char] = true
								end
								char.DescendantAdded:Connect(markDirty)
								char.DescendantRemoving:Connect(markDirty)
							end
							local parts = partCache[char]
							if dirty[char] or not parts then
								dirty[char] = false
								parts = {}
								for _, v in ipairs(char:GetDescendants()) do
									if v:IsA("BasePart") then
										parts[#parts + 1] = v
									end
								end
								partCache[char] = parts
							end
							for i = 1, #parts do
								parts[i].CanCollide = false
							end
						end
					end
				end)
			end,
		},
