			args = "<arg>",
			aliases = { "hkill" },
			callback = function(arg)
				local args = _IY_splitArgs(arg)
				local speaker = _IY_lp
				if not firetouchinterest then
					return _IY_notify(
						"Incompatible Exploit",
						"Your exploit does not support this command (missing firetouchinterest)"
					)
				end
				if not _IY_lp.Character then
					return
				end
				local tool = _IY_lp.Character:FindFirstChildWhichIsA("Tool")
				local handle = tool and tool:FindFirstChild("Handle")
				if not handle then
					return _IY_notify(
						"Handle Kill",
						'You need to hold a "Tool" that does damage on touch. For example a common Sword tool.'
					)
				end
				local range = tonumber(args[2]) or math.huge
				if range ~= math.huge then
					_IY_notify("Handle Kill", ("Started!\nRadius: %s"):format(tostring(range):upper()))
				end
				while task.wait() and _IY_lp.Character and tool.Parent and tool.Parent == _IY_lp.Character do
					for _, plr in next, getPlayer(args[1], _IY_lp) do
						plr = _IY_Players[plr]
						if plr ~= _IY_lp and plr.Character then
							local hum = plr.Character:FindFirstChildWhichIsA("Humanoid")
							local root = hum and _IY_getRoot(plr.Character)
							if
								root
								and hum.Health > 0
								and hum:GetState() ~= Enum.HumanoidStateType.Dead
								and _IY_lp:DistanceFromCharacter(root.Position) <= range
							then
								firetouchinterest(handle, root, 1)
								firetouchinterest(handle, root, 0)
							end
						end
					end
				end
				_IY_notify("Handle Kill", "Stopped!")
			end,
		},
