	function create(data)
		local insts = {}
		for i, v in pairs(data) do
			insts[v[1]] = Instance.new(v[2])
		end
		for _, v in pairs(data) do
			for prop, val in pairs(v[3]) do
				if type(val) == "table" then
					insts[v[1]][prop] = insts[val[1]]
				else
					insts[v[1]][prop] = val
				end
			end
		end
		return insts[1]
	end
	ViewportTextBox = (function()
		local funcs = {}
		funcs.Update = function(self)
			local cursorPos = self.TextBox.CursorPosition
			local text = self.TextBox.Text
			if text == "" then
				self.TextBox.Position = UDim2.new(0, 2, 0, 0)
				return
			end
			if cursorPos == -1 then
				return
			end
			local cursorText = text:sub(1, cursorPos - 1)
			local pos = nil
			local leftEnd = -self.TextBox.Position.X.Offset
			local rightEnd = leftEnd + self.View.AbsoluteSize.X
			local totalTextSize =
				TextService:GetTextSize(text, self.TextBox.TextSize, self.TextBox.Font, Vector2.new(999999999, 100)).X
			local cursorTextSize = TextService:GetTextSize(
				cursorText,
				self.TextBox.TextSize,
				self.TextBox.Font,
				Vector2.new(999999999, 100)
			).X
			if cursorTextSize > rightEnd then
				pos = math.max(-2, cursorTextSize - self.View.AbsoluteSize.X + 2)
			elseif cursorTextSize < leftEnd then
				pos = math.max(-2, cursorTextSize - 2)
			elseif totalTextSize < rightEnd then
				pos = math.max(-2, totalTextSize - self.View.AbsoluteSize.X + 2)
			end
			if pos then
				self.TextBox.Position = UDim2.new(0, -pos, 0, 0)
				self.TextBox.Size = UDim2.new(1, pos, 1, 0)
			end
		end
		local mt = {}
		mt.__index = funcs

		local function convert(textbox)
			local obj = setmetatable({ OffsetX = 0, TextBox = textbox }, mt)
			local view = Instance.new("Frame")
			view.BackgroundTransparency = textbox.BackgroundTransparency
			view.BackgroundColor3 = textbox.BackgroundColor3
			view.BorderSizePixel = textbox.BorderSizePixel
			view.BorderColor3 = textbox.BorderColor3
			view.Position = textbox.Position
			view.Size = textbox.Size
			view.ClipsDescendants = true
			view.Name = textbox.Name
			view.ZIndex = 10
			textbox.BackgroundTransparency = 1
			textbox.Position = UDim2.new(0, 4, 0, 0)
			textbox.Size = UDim2.new(1, -8, 1, 0)
			textbox.TextXAlignment = Enum.TextXAlignment.Left
			textbox.Name = "Input"
			table.insert(text1, textbox)
			table.insert(shade2, view)
			obj.View = view
			textbox.Changed:Connect(function(prop)
				if prop == "Text" or prop == "CursorPosition" or prop == "AbsoluteSize" then
					obj:Update()
				end
			end)
			obj:Update()
			view.Parent = textbox.Parent
			textbox.Parent = view
			return obj
		end
		return { convert = convert }
	end)()
	ViewportTextBox.convert(Cmdbar).View.ZIndex = 10
	ViewportTextBox.convert(Cmdbar_2).View.ZIndex = 10
	ViewportTextBox.convert(Cmdbar_3).View.ZIndex = 10

	function writefileExploit()
		if writefile then
			return true
		end
	end

	function readfileExploit()
		if readfile then
			return true
		end
	end

	function isNumber(str)
		if tonumber(str) ~= nil or str == "inf" then
			return true
		end
	end

	function vtype(o, t)
		if o == nil then
			return false
		end
		if type(o) == "userdata" then
			return typeof(o) == t
		end
		return type(o) == t
	end

	function getRoot(char)
		if char and char:FindFirstChildOfClass("Humanoid") then
			return char:FindFirstChildOfClass("Humanoid").RootPart
		else
			return nil
		end
	end

	function tools(plr)
		if
			plr:FindFirstChildOfClass("Backpack"):FindFirstChildOfClass("Tool")
			or plr.Character:FindFirstChildOfClass("Tool")
		then
			return true
		end
	end

	function r15(plr)
		if plr.Character:FindFirstChildOfClass("Humanoid").RigType == Enum.HumanoidRigType.R15 then
			return true
		end
	end

	function breakVelocity()
		local V3 = Vector3.new(0, 0, 0)
		for _, v in ipairs(Players.LocalPlayer.Character:GetDescendants()) do
			if v:IsA("BasePart") then
				v.AssemblyLinearVelocity, v.AssemblyAngularVelocity = V3, V3
			end
		end
	end

	function toClipboard(txt)
		if everyClipboard then
			everyClipboard(tostring(txt))
			notify("Clipboard", "Copied to clipboard")
		else
			notify("Clipboard", "Your exploit doesn't have the ability to use the clipboard")
		end
	end

	function chatMessage(str)
		str = tostring(str)
		if isLegacyChat then
			local chatRemote = ReplicatedStorage:FindFirstChild("SayMessageRequest", true)
			if chatRemote then
				chatRemote:FireServer(str, "All")
			end
			return
		end
		local chat = TextChatService.ChatInputBarConfiguration.TargetTextChannel
		local textChannels = TextChatService:FindFirstChild("TextChannels")
		local generalChannel = textChannels and textChannels:FindFirstChild("RBXGeneral")
		pcall(function()
			local targetChannel = generalChannel or chat
			if targetChannel then
				targetChannel:SendAsync(str)
			end
		end)
	end

	function getHierarchy(obj)
		local fullname
		local period
		if string.find(obj.Name, " ") then
			fullname = '["' .. obj.Name .. '"]'
			period = false
		else
			fullname = obj.Name
			period = true
		end
		local getS = obj
		local parent = obj
		local service = ""
		if getS.Parent ~= game then
			repeat
				getS = getS.Parent
				service = getS.ClassName
			until getS.Parent == game
		end
		if parent.Parent ~= getS then
			repeat
				parent = parent.Parent
				if string.find(tostring(parent), " ") then
					if period then
						fullname = '["' .. parent.Name .. '"].' .. fullname
					else
						fullname = '["' .. parent.Name .. '"]' .. fullname
					end
					period = false
				else
					if period then
						fullname = parent.Name .. "." .. fullname
					else
						fullname = parent.Name .. "" .. fullname
					end
					period = true
				end
			until parent.Parent == getS
		elseif string.find(tostring(parent), " ") then
			fullname = '["' .. parent.Name .. '"]'
			period = false
		end
		if period then
			return 'game:GetService("' .. service .. '").' .. fullname
		else
			return 'game:GetService("' .. service .. '")' .. fullname
		end
	end
	AllWaypoints = {}
	local cooldown = false

	function writefileCooldown(name, data)
		task.spawn(function()
			if not cooldown then
				cooldown = true
				iywritefile(name, data, true)
			else
				repeat
					wait()
				until cooldown == false
				writefileCooldown(name, data)
			end
			wait(3)
			cooldown = false
		end)
	end

	function dragGUI(gui)
		task.spawn(function()
			local dragging
			local dragInput
			local dragStart = Vector3.new(0, 0, 0)
			local startPos
			local function update(input)
				local delta = input.Position - dragStart
				local Position = UDim2.new(
					startPos.X.Scale,
					startPos.X.Offset + delta.X,
					startPos.Y.Scale,
					startPos.Y.Offset + delta.Y
				)
				TweenService:Create(gui, TweenInfo.new(0.20), { Position = Position }):Play()
			end
			gui.InputBegan:Connect(function(input)
				if
					input.UserInputType == Enum.UserInputType.MouseButton1
					or input.UserInputType == Enum.UserInputType.Touch
				then
					dragging = true
					dragStart = input.Position
					startPos = gui.Position
					input.Changed:Connect(function()
						if input.UserInputState == Enum.UserInputState.End then
							dragging = false
						end
					end)
				end
			end)
			gui.InputChanged:Connect(function(input)
				if
					input.UserInputType == Enum.UserInputType.MouseMovement
					or input.UserInputType == Enum.UserInputType.Touch
				then
					dragInput = input
				end
			end)
			UserInputService.InputChanged:Connect(function(input)
				if input == dragInput and dragging then
					update(input)
				end
			end)
		end)
	end
