	task.defer(function()
		for i = 1, #CMDs do
			local newcmd = Example:Clone()
			newcmd.Parent = CMDsF
			newcmd.Visible = false
			newcmd.Text = CMDs[i].NAME
			newcmd.Name = "CMD"
			table.insert(text1, newcmd)
			if CMDs[i].DESC ~= "" then
				newcmd:SetAttribute("Title", CMDs[i].NAME)
				newcmd:SetAttribute("Desc", CMDs[i].DESC)
				newcmd.MouseButton1Down:Connect(function()
					if not IsOnMobile and newcmd.Visible and newcmd.TextTransparency == 0 then
						local currentText = Cmdbar.Text
						Cmdbar:CaptureFocus()
						autoComplete(newcmd.Text, currentText)
						maximizeHolder()
					end
				end)
			end
		end
		IndexContents("", true)
	end)

	function checkTT()
		local t
		local guisAtPosition = COREGUI:GetGuiObjectsAtPosition(IYMouse.X, IYMouse.Y)
		for _, gui in pairs(guisAtPosition) do
			if gui.Parent == CMDsF then
				t = gui
			end
		end
		if t ~= nil and t:GetAttribute("Title") ~= nil then
			local x = IYMouse.X
			local y = IYMouse.Y
			local xP
			local yP
			if IYMouse.X > 200 then
				xP = x - 201
			else
				xP = x + 21
			end
			if IYMouse.Y > (IYMouse.ViewSizeY - 96) then
				yP = y - 97
			else
				yP = y
			end
			Tooltip.Position = UDim2.new(0, xP, 0, yP)
			Description.Text = t:GetAttribute("Desc")
			if t:GetAttribute("Title") ~= nil then
				Title_3.Text = t:GetAttribute("Title")
			else
				Title_3.Text = ""
			end
			Tooltip.Visible = true
		else
			Tooltip.Visible = false
		end
	end

	function FindInTable(tbl, val)
		if tbl == nil then
			return false
		end
		for _, v in pairs(tbl) do
			if v == val then
				return true
			end
		end
		return false
	end

	function GetInTable(Table, Name)
		for i = 1, #Table do
			if Table[i] == Name then
				return i
			end
		end
		return false
	end

	function permadeath(plr)
		if replicatesignal then
			replicatesignal(plr.ConnectDiedSignalBackend)
			task.wait(Players.RespawnTime - 0.1)
		end
	end

	function respawn(plr)
		if invisRunning then
			TurnVisible()
		end
		local char = plr.Character
		if onyxAPI and onyxAPI.is_reanimated and onyxAPI.is_reanimated() then
			char = onyxAPI.get_real_character(plr) or char
		end
		if char then
			local hum = char:FindFirstChildWhichIsA("Humanoid")
			if hum then
				hum:ChangeState(Enum.HumanoidStateType.Dead)
			end
			char:BreakJoints()
		end
	end
	local refreshCmd = false

	function refresh(plr)
		refreshCmd = true
		local root = getRoot(plr.Character)
		if not root then
			respawn(plr)
			refreshCmd = false
			return
		end
		local pos = root.CFrame
		local pos1 = workspace.CurrentCamera.CFrame
		respawn(plr)
		task.spawn(function()
			local char = plr.CharacterAdded:Wait()
			local humanoid = char:WaitForChild("Humanoid", 5) or char:FindFirstChildOfClass("Humanoid")
			if humanoid then
				local hrp = char:WaitForChild("HumanoidRootPart", 5)
				if hrp then
					task.wait(0.1)
					hrp.CFrame = pos
					workspace.CurrentCamera.CFrame = pos1
				end
			end
			refreshCmd = false
		end)
	end
	local lastDeath

	function onDied()
		task.spawn(function()
			if
				pcall(function()
					Players.LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
				end) and Players.LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
			then
				Players.LocalPlayer.Character:FindFirstChildOfClass("Humanoid").Died:Connect(function()
					if getRoot(Players.LocalPlayer.Character) then
						lastDeath = getRoot(Players.LocalPlayer.Character).CFrame
					end
				end)
			else
				wait(2)
				onDied()
			end
		end)
	end
	Clip = true
	spDelay = 0.1
	Players.LocalPlayer.CharacterAdded:Connect(function()
		NOFLY()
		Floating = false
		if not Clip then
			execCmd("clip")
		end
		repeat
			wait()
		until getRoot(Players.LocalPlayer.Character)
		pcall(function()
			if spawnpoint and not refreshCmd and spawnpos ~= nil then
				wait(spDelay)
				getRoot(Players.LocalPlayer.Character).CFrame = spawnpos
			end
		end)
		onDied()
	end)
	onDied()
	local booly = {
		truthy = {
			["true"] = true,
			["t"] = true,
			["1"] = true,
			yes = true,
			y = true,
			on = true,
			enable = true,
			enabled = true,
		},
		falsy = {
			["false"] = true,
			["f"] = true,
			["0"] = true,
			no = true,
			n = true,
			off = true,
			disable = true,
			disabled = true,
		},
	}
	parseBoolean = function(raw, default)
		raw = tostring(raw)
		if booly.truthy[raw] then
			return true
		end
		if booly.falsy[raw] then
			return false
		end
		return default or false
	end
	getstring = function(begin, args)
		return table.concat(args or cargs, " ", begin)
	end
	findCmd = function(cmd_name)
		for i, v in pairs(cmds) do
			if v.NAME:lower() == cmd_name:lower() or FindInTable(v.ALIAS, cmd_name:lower()) then
				return v
			end
		end
		return customAlias[cmd_name:lower()]
	end
	splitString = function(str, delim)
		local broken = {}
		if delim == nil then
			delim = ","
		end
		for w in string.gmatch(str, "[^" .. delim .. "]+") do
			table.insert(broken, w)
		end
		return broken
	end
	cmdHistory = {}
	local lastCmds = {}
	local historyCount = 0
	local split = " "
	local lastBreakTime = 0
	execCmd = function(cmdStr, speaker, store)
		cmdStr = cmdStr:gsub("%s+$", "")
		task.spawn(function()
			local rawCmdStr = cmdStr
			cmdStr = string.gsub(cmdStr, "\\\\", "%%BackSlash%%")
			local commandsToRun = splitString(cmdStr, "\\")
			for i, v in pairs(commandsToRun) do
				v = string.gsub(v, "%%BackSlash%%", "\\")
				local x, y, num = v:find("^(%d+)%^")
				local cmdDelay = 0
				local infTimes = false
				if num then
					v = v:sub(y + 1)
					local x, y, del = v:find("^([%d%.]+)%^")
					if del then
						v = v:sub(y + 1)
						cmdDelay = tonumber(del) or 0
					end
				else
					local x, y = v:find("^inf%^")
					if x then
						infTimes = true
						v = v:sub(y + 1)
						local x, y, del = v:find("^([%d%.]+)%^")
						if del then
							v = v:sub(y + 1)
							del = tonumber(del) or 1
							cmdDelay = (del > 0 and del or 1)
						else
							cmdDelay = 1
						end
					end
				end
				num = tonumber(num or 1)
				if v:sub(1, 1) == "!" then
					local chunks = splitString(v:sub(2), split)
					if chunks[1] and lastCmds[chunks[1]] then
						v = lastCmds[chunks[1]]
					end
				end
				local args = splitString(v, split)
				local cmdName = args[1]
				local cmd = findCmd(cmdName)
				if cmd then
					table.remove(args, 1)
					cargs = args
					if not speaker then
						speaker = Players.LocalPlayer
					end
					if store then
						if speaker == Players.LocalPlayer then
							if
								cmdHistory[1] ~= rawCmdStr
								and rawCmdStr:sub(1, 11) ~= "lastcommand"
								and rawCmdStr:sub(1, 7) ~= "lastcmd"
							then
								table.insert(cmdHistory, 1, rawCmdStr)
							end
						end
						if #cmdHistory > 30 then
							table.remove(cmdHistory)
						end
						lastCmds[cmdName] = v
					end
					local cmdStartTime = tick()
					if infTimes then
						while lastBreakTime < cmdStartTime do
							local success, err = pcall(cmd.FUNC, args, speaker)
							if not success and _G.IY_DEBUG then
								warn("Command Error:", cmdName, err)
							end
							wait(cmdDelay)
						end
					else
						for rep = 1, num do
							if lastBreakTime > cmdStartTime then
								break
							end
							local success, err = pcall(function()
								cmd.FUNC(args, speaker)
							end)
							if not success and _G.IY_DEBUG then
								warn("Command Error:", cmdName, err)
							end
							if cmdDelay ~= 0 then
								wait(cmdDelay)
							end
						end
					end
				end
			end
		end)
	end
	addcmd = function(name, alias, func, plgn)
		cmds[#cmds + 1] = {
			NAME = name,
			ALIAS = alias or {},
			FUNC = func,
			PLUGIN = plgn,
		}
	end
	removecmd = function(cmd)
		if cmd ~= " " then
			for i = #cmds, 1, -1 do
				if cmds[i].NAME == cmd or FindInTable(cmds[i].ALIAS, cmd) then
					table.remove(cmds, i)
					for a, c in pairs(CMDsF:GetChildren()) do
						if
							string.find(c.Text, "^" .. cmd .. "$")
							or string.find(c.Text, "^" .. cmd .. " ")
							or string.find(c.Text, " " .. cmd .. "$")
							or string.find(c.Text, " " .. cmd .. " ")
						then
							c.TextTransparency = 0.7
							c.MouseButton1Click:Connect(function()
								notify(c.Text, "Command has been disabled by you or a plugin")
							end)
						end
					end
				end
			end
		end
	end

	function overridecmd(name, func)
		local cmd = findCmd(name)
		if cmd and cmd.FUNC then
			cmd.FUNC = func
		end
	end

	function addbind(cmd, key, iskeyup, toggle)
		if toggle then
			binds[#binds + 1] = {
				COMMAND = cmd,
				KEY = key,
				ISKEYUP = iskeyup,
				TOGGLE = toggle,
			}
		else
			binds[#binds + 1] = {
				COMMAND = cmd,
				KEY = key,
				ISKEYUP = iskeyup,
			}
		end
	end

	function addcmdtext(text, name, desc)
		local newcmd = Example:Clone()
		local tooltipText = tostring(text)
		local tooltipDesc = tostring(desc)
		newcmd.Parent = CMDsF
		newcmd.Visible = false
		newcmd.Text = text
		newcmd.Name = "PLUGIN_" .. name
		table.insert(text1, newcmd)
		if desc and desc ~= "" then
			newcmd:SetAttribute("Title", tooltipText)
			newcmd:SetAttribute("Desc", tooltipDesc)
			newcmd.MouseButton1Down:Connect(function()
				if newcmd.Visible and newcmd.TextTransparency == 0 then
					Cmdbar:CaptureFocus()
					autoComplete(newcmd.Text)
					maximizeHolder()
				end
			end)
		end
	end
	local WorldToScreen = function(Object)
		local ObjectVector = workspace.CurrentCamera:WorldToScreenPoint(Object.Position)
		return Vector2.new(ObjectVector.X, ObjectVector.Y)
	end
	local MousePositionToVector2 = function()
		return Vector2.new(IYMouse.X, IYMouse.Y)
	end
	local GetClosestPlayerFromCursor = function()
		local found = nil
		local ClosestDistance = math.huge
		for i, v in pairs(Players:GetPlayers()) do
			if v ~= Players.LocalPlayer and v.Character and v.Character:FindFirstChildOfClass("Humanoid") then
				for k, x in pairs(v.Character:GetChildren()) do
					if string.find(x.Name, "Torso") then
						local Distance = (WorldToScreen(x) - MousePositionToVector2()).Magnitude
						if Distance < ClosestDistance then
							ClosestDistance = Distance
							found = v
						end
					end
				end
			end
		end
		return found
	end
	SpecialPlayerCases = {
		["all"] = function(speaker)
			return Players:GetPlayers()
		end,
		["others"] = function(speaker)
			local plrs = {}
			for i, v in pairs(Players:GetPlayers()) do
				if v ~= speaker then
					table.insert(plrs, v)
				end
			end
			return plrs
		end,
		["me"] = function(speaker)
			return { speaker }
		end,
		["#(%d+)"] = function(speaker, args, currentList)
			local returns = {}
			local randAmount = tonumber(args[1])
			local players = { unpack(currentList) }
			for i = 1, randAmount do
				if #players == 0 then
					break
				end
				local randIndex = math.random(1, #players)
				table.insert(returns, players[randIndex])
				table.remove(players, randIndex)
			end
			return returns
		end,
		["random"] = function(speaker, args, currentList)
			local players = Players:GetPlayers()
			local localplayer = Players.LocalPlayer
			table.remove(players, table.find(players, localplayer))
			return { players[math.random(1, #players)] }
		end,
		["%%(.+)"] = function(speaker, args)
			local returns = {}
			local team = args[1]
			for _, plr in pairs(Players:GetPlayers()) do
				if plr.Team and string.sub(string.lower(plr.Team.Name), 1, #team) == string.lower(team) then
					table.insert(returns, plr)
				end
			end
			return returns
		end,
		["allies"] = function(speaker)
			local returns = {}
			local team = speaker.Team
			for _, plr in pairs(Players:GetPlayers()) do
				if plr.Team == team then
					table.insert(returns, plr)
				end
			end
			return returns
		end,
		["enemies"] = function(speaker)
			local returns = {}
			local team = speaker.Team
			for _, plr in pairs(Players:GetPlayers()) do
				if plr.Team ~= team then
					table.insert(returns, plr)
				end
			end
			return returns
		end,
		["team"] = function(speaker)
			local returns = {}
			local team = speaker.Team
			for _, plr in pairs(Players:GetPlayers()) do
				if plr.Team == team then
					table.insert(returns, plr)
				end
			end
			return returns
		end,
		["nonteam"] = function(speaker)
			local returns = {}
			local team = speaker.Team
			for _, plr in pairs(Players:GetPlayers()) do
				if plr.Team ~= team then
					table.insert(returns, plr)
				end
			end
			return returns
		end,
		["friends"] = function(speaker, args)
			local returns = {}
			for _, plr in pairs(Players:GetPlayers()) do
				if plr:IsFriendsWith(speaker.UserId) and plr ~= speaker then
					table.insert(returns, plr)
				end
			end
			return returns
		end,
		["nonfriends"] = function(speaker, args)
			local returns = {}
			for _, plr in pairs(Players:GetPlayers()) do
				if not plr:IsFriendsWith(speaker.UserId) and plr ~= speaker then
					table.insert(returns, plr)
				end
			end
			return returns
		end,
		["guests"] = function(speaker, args)
			local returns = {}
			for _, plr in pairs(Players:GetPlayers()) do
				if plr.Guest then
					table.insert(returns, plr)
				end
			end
			return returns
		end,
		["bacons"] = function(speaker, args)
			local returns = {}
			for _, plr in pairs(Players:GetPlayers()) do
				if plr.Character:FindFirstChild("Pal Hair") or plr.Character:FindFirstChild("Kate Hair") then
					table.insert(returns, plr)
				end
			end
			return returns
		end,
		["age(%d+)"] = function(speaker, args)
			local returns = {}
			local age = tonumber(args[1])
			if not age == nil then
				return
			end
			for _, plr in pairs(Players:GetPlayers()) do
				if plr.AccountAge <= age then
					table.insert(returns, plr)
				end
			end
			return returns
		end,
		["nearest"] = function(speaker, args, currentList)
			local speakerChar = speaker.Character
			if not speakerChar or not getRoot(speakerChar) then
				return
			end
			local lowest = math.huge
			local NearestPlayer = nil
			for _, plr in pairs(currentList) do
				if plr ~= speaker and plr.Character then
					local distance = plr:DistanceFromCharacter(getRoot(speakerChar).Position)
					if distance < lowest then
						lowest = distance
						NearestPlayer = { plr }
					end
				end
			end
			return NearestPlayer
		end,
		["farthest"] = function(speaker, args, currentList)
			local speakerChar = speaker.Character
			if not speakerChar or not getRoot(speakerChar) then
				return
			end
			local highest = 0
			local Farthest = nil
			for _, plr in pairs(currentList) do
				if plr ~= speaker and plr.Character then
					local distance = plr:DistanceFromCharacter(getRoot(speakerChar).Position)
					if distance > highest then
						highest = distance
						Farthest = { plr }
					end
				end
			end
			return Farthest
		end,
		["group(%d+)"] = function(speaker, args)
			local returns = {}
			local groupID = tonumber(args[1])
			for _, plr in pairs(Players:GetPlayers()) do
				if plr:IsInGroup(groupID) then
					table.insert(returns, plr)
				end
			end
			return returns
		end,
		["alive"] = function(speaker, args)
			local returns = {}
			for _, plr in pairs(Players:GetPlayers()) do
				if
					plr.Character
					and plr.Character:FindFirstChildOfClass("Humanoid")
					and plr.Character:FindFirstChildOfClass("Humanoid").Health > 0
				then
					table.insert(returns, plr)
				end
			end
			return returns
		end,
		["dead"] = function(speaker, args)
			local returns = {}
			for _, plr in pairs(Players:GetPlayers()) do
				if
					(not plr.Character or not plr.Character:FindFirstChildOfClass("Humanoid"))
					or plr.Character:FindFirstChildOfClass("Humanoid").Health <= 0
				then
					table.insert(returns, plr)
				end
			end
			return returns
		end,
		["rad(%d+)"] = function(speaker, args)
			local returns = {}
			local radius = tonumber(args[1])
			local speakerChar = speaker.Character
			if not speakerChar or not getRoot(speakerChar) then
				return
			end
			for _, plr in pairs(Players:GetPlayers()) do
				if plr.Character and getRoot(plr.Character) then
					local magnitude = (getRoot(plr.Character).Position - getRoot(speakerChar).Position).magnitude
					if magnitude <= radius then
						table.insert(returns, plr)
					end
				end
			end
			return returns
		end,
		["cursor"] = function(speaker)
			local plrs = {}
			local v = GetClosestPlayerFromCursor()
			if v ~= nil then
				table.insert(plrs, v)
			end
			return plrs
		end,
		["npcs"] = function(speaker, args)
			local returns = {}
			for _, v in pairs(workspace:GetDescendants()) do
				if
					v:IsA("Model")
					and getRoot(v)
					and v:FindFirstChildWhichIsA("Humanoid")
					and Players:GetPlayerFromCharacter(v) == nil
				then
					local clone = Instance.new("Player")
					clone.Name = v.Name .. " - " .. v:FindFirstChildWhichIsA("Humanoid").DisplayName
					clone.Character = v
					table.insert(returns, clone)
				end
			end
			return returns
		end,
	}

	function toTokens(str)
		local tokens = {}
		for op, name in string.gmatch(str, "([+-])([^+-]+)") do
			table.insert(tokens, { Operator = op, Name = name })
		end
		return tokens
	end

	function onlyIncludeInTable(tab, matches)
		local matchTable = {}
		local resultTable = {}
		for i, v in pairs(matches) do
			matchTable[v.Name] = true
		end
		for i, v in pairs(tab) do
			if matchTable[v.Name] then
				table.insert(resultTable, v)
			end
		end
		return resultTable
	end

	function removeTableMatches(tab, matches)
		local matchTable = {}
		local resultTable = {}
		for i, v in pairs(matches) do
			matchTable[v.Name] = true
		end
		for i, v in pairs(tab) do
			if not matchTable[v.Name] then
				table.insert(resultTable, v)
			end
		end
		return resultTable
	end

	function getPlayersByName(Name)
		if not Name or Name == "" then
			return {}
		end
		local cleanName = string.lower(Name)
		if cleanName:sub(1, 1) == "@" then
			cleanName = cleanName:sub(2)
		end
		local Len = #cleanName
		if Len == 0 then
			return {}
		end
		local exact = {}
		local prefix = {}
		local substring = {}
		for _, v in pairs(Players:GetPlayers()) do
			local uname = string.lower(v.Name)
			local dname = string.lower(v.DisplayName or v.Name)
			if uname == cleanName or dname == cleanName then
				table.insert(exact, v)
			elseif string.sub(uname, 1, Len) == cleanName or string.sub(dname, 1, Len) == cleanName then
				table.insert(prefix, v)
			elseif string.find(uname, cleanName, 1, true) or string.find(dname, cleanName, 1, true) then
				table.insert(substring, v)
			end
		end
		if #exact > 0 then
			return exact
		end
		if #prefix > 0 then
			return prefix
		end
		return substring
	end

	function getPlayer(list, speaker)
		speaker = speaker or Players.LocalPlayer
		if list == nil or list == "" or list == "me" or list == "self" then
			return { speaker.Name }
		end
		local nameList = splitString(list, ",")
		local foundList = {}
		for _, name in pairs(nameList) do
			name = name:match("^%s*(.-)%s*$")
			if name == "me" or name == "self" then
				table.insert(foundList, speaker)
			elseif name == "others" then
				for _, p in ipairs(Players:GetPlayers()) do
					if p ~= speaker then
						table.insert(foundList, p)
					end
				end
			elseif name == "all" then
				for _, p in ipairs(Players:GetPlayers()) do
					table.insert(foundList, p)
				end
			elseif name ~= "" then
				if string.sub(name, 1, 1) ~= "+" and string.sub(name, 1, 1) ~= "-" then
					name = "+" .. name
				end
				local tokens = toTokens(name)
				local initialPlayers = Players:GetPlayers()
				for i, v in pairs(tokens) do
					if v.Operator == "+" then
						local tokenContent = v.Name
						local foundCase = false
						for regex, case in pairs(SpecialPlayerCases) do
							local matches = { string.match(tokenContent, "^" .. regex .. "$") }
							if #matches > 0 then
								foundCase = true
								initialPlayers =
									onlyIncludeInTable(initialPlayers, case(speaker, matches, initialPlayers))
							end
						end
						if not foundCase then
							initialPlayers = onlyIncludeInTable(initialPlayers, getPlayersByName(tokenContent))
						end
					else
						local tokenContent = v.Name
						local foundCase = false
						for regex, case in pairs(SpecialPlayerCases) do
							local matches = { string.match(tokenContent, "^" .. regex .. "$") }
							if #matches > 0 then
								foundCase = true
								initialPlayers =
									removeTableMatches(initialPlayers, case(speaker, matches, initialPlayers))
							end
						end
						if not foundCase then
							initialPlayers = removeTableMatches(initialPlayers, getPlayersByName(tokenContent))
						end
					end
				end
				for i, v in pairs(initialPlayers) do
					table.insert(foundList, v)
				end
			end
		end
		local foundNames = {}
		for i, v in pairs(foundList) do
			if not table.find(foundNames, v.Name) then
				table.insert(foundNames, v.Name)
			end
		end
		return foundNames
	end

	function formatUsername(player)
		if player.DisplayName ~= player.Name then
			return string.format("%s (%s)", player.Name, player.DisplayName)
		end
		return player.Name
	end
	getprfx = function(strn)
		if strn:sub(1, string.len(prefix)) == prefix then
			return { "cmd", string.len(prefix) + 1 }
		end
		return
	end

	function do_exec(str, plr)
		str = str:gsub("/e ", "")
		local t = getprfx(str)
		if not t then
			return
		end
		str = str:sub(t[2])
		if t[1] == "cmd" then
			execCmd(str, plr, true)
			IndexContents("", true, false, true)
			CMDsF.CanvasPosition = canvasPos
		end
	end
	lastTextBoxString, lastTextBoxCon, lastEnteredString = nil, nil, nil
	UserInputService.TextBoxFocused:Connect(function(obj)
		if lastTextBoxCon then
			lastTextBoxCon:Disconnect()
		end
		if obj == Cmdbar then
			lastTextBoxString = nil
			return
		end
		lastTextBoxString = obj.Text
		lastTextBoxCon = obj:GetPropertyChangedSignal("Text"):Connect(function()
			if
				not (
					UserInputService:IsKeyDown(Enum.KeyCode.Return)
					or UserInputService:IsKeyDown(Enum.KeyCode.KeypadEnter)
				)
			then
				lastTextBoxString = obj.Text
			end
		end)
	end)
	UserInputService.InputBegan:Connect(function(input, gameProcessed)
		if gameProcessed then
			if Cmdbar and Cmdbar:IsFocused() then
				if input.KeyCode == Enum.KeyCode.Up then
					historyCount = historyCount + 1
					if historyCount > #cmdHistory then
						historyCount = #cmdHistory
					end
					Cmdbar.Text = cmdHistory[historyCount] or ""
					Cmdbar.CursorPosition = 1020
				elseif input.KeyCode == Enum.KeyCode.Down then
					historyCount = historyCount - 1
					if historyCount < 0 then
						historyCount = 0
					end
					Cmdbar.Text = cmdHistory[historyCount] or ""
					Cmdbar.CursorPosition = 1020
				end
			elseif input.KeyCode == Enum.KeyCode.Return or input.KeyCode == Enum.KeyCode.KeypadEnter then
				lastEnteredString = lastTextBoxString
			end
		end
	end)
	Players.LocalPlayer.Chatted:Connect(function()
		wait()
		if lastEnteredString then
			local message = lastEnteredString
			lastEnteredString = nil
			pcall(do_exec, message, Players.LocalPlayer)
		end
	end)
	Cmdbar.PlaceholderText = "Command Bar (" .. prefix .. ")"
	Cmdbar:GetPropertyChangedSignal("Text"):Connect(function()
		if Cmdbar:IsFocused() then
			IndexContents(Cmdbar.Text, true, true)
		end
	end)
	local tabComplete = nil
	tabAllowed = true
	Cmdbar.FocusLost:Connect(function(enterpressed)
