			IndexContents("", true, false, true)
			if SettingsOpen == true then
				wait(0.2)
				Settings:TweenPosition(UDim2.new(0, 0, 0, 45), "InOut", "Quart", 0.2, true, nil)
				CMDsF.Visible = false
			end
		end
		CMDsF.CanvasPosition = canvasPos
	end)
	Cmdbar.Focused:Connect(function()
		historyCount = 0
		canvasPos = CMDsF.CanvasPosition
		if SettingsOpen == true then
			wait(0.2)
			CMDsF.Visible = true
			Settings:TweenPosition(UDim2.new(0, 0, 0, 220), "InOut", "Quart", 0.2, true, nil)
		end
		tabComplete = UserInputService.InputBegan:Connect(function(input, gameProcessed)
			if Cmdbar:IsFocused() then
				if tabAllowed == true and input.KeyCode == Enum.KeyCode.Tab and topCommand ~= nil then
					autoComplete(topCommand)
				end
			else
				tabComplete:Disconnect()
			end
		end)
	end)
	ESPenabled = false
	CHMSenabled = false

	function round(num, numDecimalPlaces)
		local mult = 10 ^ (numDecimalPlaces or 0)
		return math.floor(num * mult + 0.5) / mult
	end

	function ESP(plr, logic)
		task.spawn(function()
			for i, v in pairs(COREGUI:GetChildren()) do
				if v.Name == plr.Name .. "_ESP" then
					v:Destroy()
				end
			end
			wait()
			if
				plr.Character
				and plr.Name ~= Players.LocalPlayer.Name
				and not COREGUI:FindFirstChild(plr.Name .. "_ESP")
			then
				local ESPholder = Instance.new("Folder")
				ESPholder.Name = plr.Name .. "_ESP"
				ESPholder.Parent = COREGUI
				repeat
					wait(1)
				until plr.Character and getRoot(plr.Character) and plr.Character:FindFirstChildOfClass("Humanoid")
				for b, n in pairs(plr.Character:GetChildren()) do
					if n:IsA("BasePart") then
						local a = Instance.new("BoxHandleAdornment")
						a.Name = plr.Name
						a.Parent = ESPholder
						a.Adornee = n
						a.AlwaysOnTop = true
						a.ZIndex = 10
						a.Size = n.Size
						a.Transparency = espTransparency
						if logic == true then
							local colorName: string = if plr.TeamColor == Players.LocalPlayer.TeamColor then "Bright green" else "Bright red"
							local bc = BrickColor.new(colorName)
							pcall(function() (a :: any).Color = bc end)
							pcall(function() a.Color3 = bc.Color end)
						else
							local bc = plr.TeamColor
							pcall(function() (a :: any).Color = bc end)
							if bc and typeof(bc) == "BrickColor" then
								pcall(function() a.Color3 = bc.Color end)
							end
						end
					end
				end
				if plr.Character and plr.Character:FindFirstChild("Head") then
					local BillboardGui = Instance.new("BillboardGui")
					local TextLabel = Instance.new("TextLabel")
					BillboardGui.Adornee = plr.Character.Head
					BillboardGui.Name = plr.Name
					BillboardGui.Parent = ESPholder
					BillboardGui.Size = UDim2.new(0, 100, 0, 150)
					BillboardGui.StudsOffset = Vector3.new(0, 1, 0)
					BillboardGui.AlwaysOnTop = true
					TextLabel.Parent = BillboardGui
					TextLabel.BackgroundTransparency = 1
					TextLabel.Position = UDim2.new(0, 0, 0, -50)
					TextLabel.Size = UDim2.new(0, 100, 0, 100)
					TextLabel.Font = Enum.Font.SourceSansSemibold
					TextLabel.TextSize = 20
					TextLabel.TextColor3 = Color3.new(1, 1, 1)
					TextLabel.TextStrokeTransparency = 0
					TextLabel.TextYAlignment = Enum.TextYAlignment.Bottom
					TextLabel.Text = "Name: " .. plr.Name
					TextLabel.ZIndex = 10
					local espLoopFunc
					local teamChange
					local addedFunc
					addedFunc = plr.CharacterAdded:Connect(function()
						if ESPenabled then
							espLoopFunc:Disconnect()
							teamChange:Disconnect()
							ESPholder:Destroy()
							repeat
								wait(1)
							until getRoot(plr.Character) and plr.Character:FindFirstChildOfClass("Humanoid")
							ESP(plr, logic)
							addedFunc:Disconnect()
						else
							teamChange:Disconnect()
							addedFunc:Disconnect()
						end
					end)
					teamChange = plr:GetPropertyChangedSignal("TeamColor"):Connect(function()
						if ESPenabled then
							espLoopFunc:Disconnect()
							addedFunc:Disconnect()
							ESPholder:Destroy()
							repeat
								wait(1)
							until getRoot(plr.Character) and plr.Character:FindFirstChildOfClass("Humanoid")
							ESP(plr, logic)
							teamChange:Disconnect()
						else
							teamChange:Disconnect()
						end
					end)
					local lastUpdate = 0
					local espLoop = function()
						if COREGUI:FindFirstChild(plr.Name .. "_ESP") then
							local now = tick()
							if now - lastUpdate >= 0.1 then
								lastUpdate = now
								if
									plr.Character
									and getRoot(plr.Character)
									and plr.Character:FindFirstChildOfClass("Humanoid")
									and Players.LocalPlayer.Character
									and getRoot(Players.LocalPlayer.Character)
									and Players.LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
								then
									local pos = math.floor(
										(
											getRoot(Players.LocalPlayer.Character).Position
											- getRoot(plr.Character).Position
										).magnitude
									)
									TextLabel.Text = "Name: "
										.. plr.Name
										.. " | Health: "
										.. round(plr.Character:FindFirstChildOfClass("Humanoid").Health, 1)
										.. " | Studs: "
										.. pos
								end
							end
						else
							teamChange:Disconnect()
							addedFunc:Disconnect()
							espLoopFunc:Disconnect()
						end
					end
					espLoopFunc = RunService.RenderStepped:Connect(espLoop)
				end
			end
		end)
	end

