	function clicktpFunc()
		pcall(function()
			local character = Players.LocalPlayer.Character
			local humanoid = character:FindFirstChildOfClass("Humanoid")
			if humanoid and humanoid.SeatPart then
				humanoid.Sit = false
				wait(0.1)
			end
			local hipHeight = humanoid and humanoid.HipHeight > 0 and (humanoid.HipHeight + 1)
			local rootPart = getRoot(character)
			local rootPartPosition = rootPart.Position
			local hitPosition = IYMouse.Hit.Position
			local newCFrame = CFrame.new(
				hitPosition,
				Vector3.new(rootPartPosition.X, hitPosition.Y, rootPartPosition.Z)
			) * CFrame.Angles(0, math.pi, 0)
			rootPart.CFrame = newCFrame + Vector3.new(0, hipHeight or 4, 0)
			breakVelocity()
		end)
	end
	IYMouse.Button1Down:Connect(function()
		for i, v in pairs(binds) do
			if v.COMMAND == "clicktp" then
				local input = v.KEY
				if
					input == "RightClick"
					and UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton2)
					and Players.LocalPlayer.Character
				then
					clicktpFunc()
				elseif
					input == "LeftClick"
					and UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1)
					and Players.LocalPlayer.Character
				then
					clicktpFunc()
				elseif
					(function()
						local kn = getKeyName(input)
						local ok, kc = pcall(function()
							return Enum.KeyCode[kn]
						end)
						return ok and kc and UserInputService:IsKeyDown(kc)
					end)() and Players.LocalPlayer.Character
				then
					clicktpFunc()
				end
			elseif v.COMMAND == "clickdel" then
				local input = v.KEY
				if input == "RightClick" and UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton2) then
					pcall(function()
						IYMouse.Target:Destroy()
					end)
				elseif
					input == "LeftClick" and UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1)
				then
					pcall(function()
						IYMouse.Target:Destroy()
					end)
				elseif
					(function()
						local kn = getKeyName(input)
						local ok, kc = pcall(function()
							return Enum.KeyCode[kn]
						end)
						return ok and kc and UserInputService:IsKeyDown(kc)
					end)()
				then
					pcall(function()
						IYMouse.Target:Destroy()
					end)
				end
			end
		end
	end)
	PluginsGUI = PluginEditor.background

	function addPlugin(name)
		if name:lower() == "plugin file name" or name:lower() == "iy_fe.iy" or name == "iy_fe" then
			notify("Plugin Error", "Please enter a valid plugin")
		else
			local file
			local fileName
			if name:sub(-3) == ".iy" then
				pcall(function()
					file = readfile(name)
				end)
				fileName = name
			else
				pcall(function()
					file = readfile(name .. ".iy")
				end)
				fileName = name .. ".iy"
			end
			if file then
				if not FindInTable(PluginsTable, fileName) then
					table.insert(PluginsTable, fileName)
					LoadPlugin(fileName)
					refreshplugins()
					pcall(eventEditor.Refresh)
				else
					notify("Plugin Error", "This plugin is already added")
				end
			else
				notify("Plugin Error", 'Cannot locate file "' .. fileName .. '". Is the file in the correct folder?')
			end
		end
	end

	function deletePlugin(name)
		local pName = name .. ".iy"
		if name:sub(-3) == ".iy" then
			pName = name
		end
		for i = #cmds, 1, -1 do
			if cmds[i].PLUGIN == pName then
				table.remove(cmds, i)
			end
		end
		for i, v in pairs(CMDsF:GetChildren()) do
			if v.Name == "PLUGIN_" .. pName then
				v:Destroy()
			end
		end
		for i, v in pairs(PluginsTable) do
			if v == pName then
				table.remove(PluginsTable, i)
				notify("Removed Plugin", pName .. " was removed")
			end
		end
		IndexContents("", true)
		refreshplugins()
	end

	function refreshplugins(dontSave)
		if #PluginsTable > 0 then
			PluginsHint:Destroy()
		end
		if Holder_5 then
			Holder_5:ClearAllChildren()
			Holder_5.CanvasSize = UDim2.new(0, 0, 0, 10)
			for i, v in pairs(PluginsTable) do
				local pName = v
				local YSize = 25
				local Position = ((i * YSize) - YSize)
				local newplugin = Example_5:Clone()
				newplugin.Parent = Holder_5
				newplugin.Visible = true
				newplugin.Position = UDim2.new(0, 0, 0, Position + 5)
				newplugin.Text.Text = pName
				table.insert(shade2, newplugin)
				table.insert(shade2, newplugin.Text)
				table.insert(text1, newplugin.Text)
				table.insert(shade3, newplugin.Text.Delete)
				table.insert(text2, newplugin.Text.Delete)
				Holder_5.CanvasSize = UDim2.new(0, 0, 0, Position + 30)
				newplugin.Text.Delete.MouseButton1Click:Connect(function()
					deletePlugin(pName)
				end)
			end
			if not dontSave then
				updatesaves()
			end
		end
	end
	local PluginCache

	function LoadPlugin(val, startup)
		local plugin

		function CatchedPluginLoad()
			local fn, err = loadfile(val)
			if fn then
				plugin = fn()
			else
				error(err or ("Failed to load plugin file: " .. tostring(val)))
			end
		end

		function handlePluginError(plerror)
			notify("Plugin Error", 'An error occurred with the plugin, "' .. val .. '" and it could not be loaded')
			if FindInTable(PluginsTable, val) then
				for i, v in pairs(PluginsTable) do
					if v == val then
						table.remove(PluginsTable, i)
					end
				end
			end
			updatesaves()
			print("Original Error: " .. tostring(plerror))
			print("Plugin Error, stack traceback: " .. tostring(debug.traceback()))
			plugin = nil
			return false
		end
		xpcall(CatchedPluginLoad, handlePluginError)
		if plugin ~= nil then
			if not startup then
				notify(
					"Loaded Plugin",
					"Name: " .. plugin["PluginName"] .. "\n" .. "Description: " .. plugin["PluginDescription"]
				)
			end
			addcmdtext("", val)
			addcmdtext(string.upper("--" .. plugin["PluginName"]), val, plugin["PluginDescription"])
			if plugin["Commands"] then
				for i, v in pairs(plugin["Commands"]) do
					local cmdExt = ""
					local cmdName = i
					local function handleNames()
						cmdName = i
						if findCmd(cmdName .. cmdExt) then
							if isNumber(cmdExt) then
								cmdExt = cmdExt + 1
							else
								cmdExt = 1
							end
							handleNames()
						else
							cmdName = cmdName .. cmdExt
						end
					end
					handleNames()
					addcmd(cmdName, v["Aliases"], v["Function"], val)
					if v["ListName"] then
						local newName = v.ListName
						local cmdNames = { i, unpack(v.Aliases) }
						for i, v in pairs(cmdNames) do
							newName = newName:gsub(v, v .. cmdExt)
						end
						addcmdtext(newName, val, v["Description"])
					else
						addcmdtext(cmdName, val, v["Description"])
					end
				end
			end
			IndexContents("", true)
		elseif plugin == nil then
			plugin = nil
		end
	end

	function FindPlugins()
		if PluginsTable ~= nil and type(PluginsTable) == "table" then
			for i, v in pairs(PluginsTable) do
				LoadPlugin(v, true)
			end
			refreshplugins(true)
		end
	end
