	addcmd("clientantikick", { "antikick" }, function(args, speaker)
		if not hookmetamethod then
			return notify("Incompatible Exploit", "Your exploit does not support this command (missing hookmetamethod)")
		end
		local LocalPlayer = Players.LocalPlayer
		local oldhmmi
		local oldhmmnc
		local oldKickFunction
		if hookfunction then
			oldKickFunction = hookfunction(LocalPlayer.Kick, function() end)
		end
		oldhmmi = hookmetamethod(game, "__index", function(self, method)
			if self == LocalPlayer and method and tostring(method):lower() == "kick" then
				return error("Expected ':' not '.' calling member function Kick", 2)
			end
			return oldhmmi(self, method)
		end)
		oldhmmnc = hookmetamethod(game, "__namecall", function(self, ...)
			local nc = getnamecallmethod and getnamecallmethod()
			if self == LocalPlayer and nc and tostring(nc):lower() == "kick" then
				return
			end
			return oldhmmnc(self, ...)
		end)
		notify("Client Antikick", "Client anti kick is now active (only effective on localscript kick)")
	end)
	allow_rj = true
	addcmd("clientantiteleport", { "antiteleport" }, function(args, speaker)
		if not hookmetamethod then
			return notify("Incompatible Exploit", "Your exploit does not support this command (missing hookmetamethod)")
		end
		local TeleportService = TeleportService
		local oldhmmi
		local oldhmmnc
		oldhmmi = hookmetamethod(game, "__index", function(self, method)
			if self == TeleportService then
				if method and tostring(method):lower() == "teleport" then
					return error("Expected ':' not '.' calling member function Kick", 2)
				elseif method == "TeleportToPlaceInstance" then
					return error("Expected ':' not '.' calling member function TeleportToPlaceInstance", 2)
				end
			end
			return oldhmmi(self, method)
		end)
		oldhmmnc = hookmetamethod(game, "__namecall", function(self, ...)
			local nc = getnamecallmethod and getnamecallmethod()
			if
				(self == TeleportService and nc and tostring(nc):lower() == "teleport")
				or (nc and nc == "TeleportToPlaceInstance")
			then
				return
			end
			return oldhmmnc(self, ...)
		end)
		notify("Client AntiTP", "Client anti teleport is now active (only effective on localscript teleport)")
	end)
