							local distance
							for waypointIndex, waypoint in pairs(waypoints) do
								local waypointPosition = waypoint.Position
								hum:MoveTo(waypointPosition)
								repeat
									distance = (waypointPosition - hum.Parent.PrimaryPart.Position).magnitude
									wait()
								until distance <= 5
							end
						end)
						if not success then
