			if scale % 1 == 0 then
				scale = scale / 100
			end
			if scale == 0.01 then
				scale = 1
			end
			if scale == 0.02 then
				scale = 2
			end
			if scale >= 0.4 and scale <= 2 then
				guiScale = scale
			end
		else
			guiScale = defaultGuiScale
		end
		Scale.Scale = math.max(Holder.AbsoluteSize.X / 1920, guiScale)
		updatesaves()
	end)
