			local function importFromOnyx(manualTrigger)
				local importedAnimsCount = 0
				local importedBindsCount = 0
				if not isfolder(customsFolderPath) then
					makefolder(customsFolderPath)
				end
				local resolvedFolder = nil
				local foldersToCheck = { "ReanimData", "Onyx/customs", "OnyxV2Folder/customs", "OnyxV2Folder", "Onyx" }
				for _, f in ipairs(foldersToCheck) do
					if isfolder and isfolder(f) then
						resolvedFolder = f
						break
					end
				end
				local function readOnyxFile(fname)
					if resolvedFolder then
						local path = resolvedFolder .. "/" .. fname
						local ok, res = pcall(readfile, path)
						if ok and type(res) == "string" and res ~= "" then
							return res
						end
					end
					local paths = {
						"ReanimData/" .. fname,
						fname,
						"OnyxV2Folder/" .. fname,
						"Onyx/" .. fname,
					}
					for _, p in ipairs(paths) do
						local ok, res = pcall(readfile, p)
						if ok and type(res) == "string" and res ~= "" then
							return res
						end
					end
					return nil
				end
				local function decodeJSON(str)
					if not str or str == "" then
						return nil
					end
					local cleaned = str:gsub("^" .. string.char(239, 187, 191), ""):gsub("\r\n", "\n"):gsub("\r", "\n")
					local ok, res = pcall(function()
						return httpService:JSONDecode(cleaned)
					end)
					return ok and type(res) == "table" and res or nil
				end
				local filesToSave = {}
				local function queueAnimForSaving(name, content)
					if not name or not content or name == "" or content == "" then
						return false
					end
					local safeName = name:gsub("[^%w%s%-_$]", ""):match("^%s*(.-)%s*$")
					if safeName == "" then
						return false
					end
					filesToSave[safeName] = content
					return true
				end
				local function saveQueuedFiles()
					local count = 0
					for name, content in pairs(filesToSave) do
						count = count + 1
						if count % 2 == 0 then
							task.wait(0.05)
						end
						local filePath = customsFolderPath .. "/" .. name .. ".lua"
						pcall(writefile, filePath, content)
					end
				end
				local customCatalogNames = {
					"onyx_custom_anims.json",
					"ReanimCustomAnims.json",
					"index.json",
					"OnyxAnimations.json",
					"CustomAnims.json",
					"custom_animations.json",
					"OnyxV2CustomAnims.json",
				}
				local batchCounter = 0
				for _, catName in ipairs(customCatalogNames) do
					local rawJson = readOnyxFile(catName)
					local data = decodeJSON(rawJson)
					if data then
						for _, entry in ipairs(data) do
							batchCounter = batchCounter + 1
							if batchCounter >= 10 then
								task.wait(0.02)
								batchCounter = 0
							end
							if type(entry) == "table" then
								local animName = entry.name or entry.Name
								local animContent = entry.url
									or entry.file
									or entry.code
									or entry.script
									or entry.id
									or entry.Id
									or (entry.animData and httpService:JSONEncode(entry.animData))
								if
									type(animContent) == "number"
									or (type(animContent) == "string" and animContent:match("^%d+$"))
								then
									animContent = "rbxassetid://" .. tostring(animContent)
								elseif
									type(animContent) == "string"
									and (
										animContent:match("%.dat$")
										or animContent:match("%.lua$")
										or animContent:match("%.json$")
										or animContent:find("/")
									)
								then
									local fileData = readOnyxFile(animContent)
										or readOnyxFile((animContent:gsub("^ReanimData/", "")))
									if fileData then
										animContent = fileData
									end
								end
								if
									animName
									and animContent
									and animName ~= ""
									and type(animContent) == "string"
									and animContent ~= ""
								then
									local sanitized = animName:gsub("[^%w%s%-_$]", ""):match("^%s*(.-)%s*$")
									if sanitized ~= "" and not transformCache[sanitized] then
										if queueAnimForSaving(sanitized, animContent) then
											transformCache[sanitized] = animContent
											importedAnimsCount = importedAnimsCount + 1
										end
									end
								end
							end
						end
						for key, val in pairs(data) do
							batchCounter = batchCounter + 1
							if batchCounter >= 10 then
								task.wait(0.02)
								batchCounter = 0
							end
							if
								type(key) == "string"
								and (type(val) == "string" or type(val) == "number" or type(val) == "table")
							then
								local animScript = type(val) == "string" and val
									or (type(val) == "number" and "rbxassetid://" .. tostring(val))
									or (
										val.code
										or val.script
										or val.url
										or val.id
										or (val.animData and httpService:JSONEncode(val.animData))
									)
								if type(animScript) == "string" then
									if animScript:match("^%d+$") then
										animScript = "rbxassetid://" .. animScript
									elseif
										animScript:match("%.dat$")
										or animScript:match("%.lua$")
										or animScript:find("/")
									then
										local fileData = readOnyxFile(animScript)
											or readOnyxFile((animScript:gsub("^ReanimData/", "")))
										if fileData then
											animScript = fileData
										end
									end
									local sanitized = key:gsub("[^%w%s%-_$]", ""):match("^%s*(.-)%s*$")
									if sanitized ~= "" and not transformCache[sanitized] then
										if queueAnimForSaving(sanitized, animScript) then
											transformCache[sanitized] = animScript
											importedAnimsCount = importedAnimsCount + 1
										end
									end
								end
							end
						end
					end
				end
				local onyxFolders = {
					"slate/reanimation/customs",
					"slate/reanimation",
					"slate/customs",
					"customs",
					"ReanimData",
					"Onyx/customs",
					"OnyxV2Folder/customs",
				}
				local onyxIgnoredFiles = {
					reanimfavorites = true,
					reanimkeybinds = true,
					reanimspeedkeys = true,
					reanimstates = true,
					onlineanimationscache = true,
					index = true,
					reanimcustomanims = true,
					reanimautoimportdone = true,
					editorpreview = true,
					reanimreversekey = true,
					reanimreversespeed = true,
					reanimrevspeedkeys = true,
					reanimfortnitewheelkey = true,
					reanimmobilewheelbtn = true,
				}
				batchCounter = 0
				for _, folder in ipairs(onyxFolders) do
					if isfolder and isfolder(folder) then
						local ok, files = pcall(listfiles, folder)
						if ok and type(files) == "table" then
							for _, f in ipairs(files) do
								batchCounter = batchCounter + 1
								if batchCounter >= 10 then
									task.wait(0.02)
									batchCounter = 0
								end
								local cleanF = f:gsub("\\\\", "/"):gsub("\\", "/")
								local fileBase = cleanF:match("([^/]+)$")
								if fileBase then
									local extStart = fileBase:find("%.[^%.]+$")
									local ext = extStart and fileBase:sub(extStart):lower() or ""
									local rawName = extStart and fileBase:sub(1, extStart - 1) or fileBase
									local lowerName = rawName:lower()
									if
										ext == ".lua"
										or ext == ".json"
										or ext == ".txt"
										or ext == ".dat"
										or ext == ""
									then
										if
											not lowerName:match("^anim_%d+$")
											and not onyxIgnoredFiles[lowerName]
											and not lowerName:match("[Ss]ettings")
											and not lowerName:match("[Cc]onfig")
										then
											local cleanName = rawName
												:gsub("^custom_", "")
												:gsub("[^%w%s%-_%$%#%@%!]", "")
												:match("^%s*(.-)%s*$")
											if cleanName ~= "" and not transformCache[cleanName] then
												local okRead, code = pcall(readfile, folder .. "/" .. fileBase)
												if okRead and type(code) == "string" and code ~= "" then
													if queueAnimForSaving(cleanName, code) then
														transformCache[cleanName] = code
														importedAnimsCount = importedAnimsCount + 1
													end
												end
											end
										end
									end
								end
							end
						end
					end
				end
				local rawFavs = decodeJSON(readOnyxFile("ReanimFavorites.json"))
					or decodeJSON(readOnyxFile("OnyxFavorites.json"))
				if rawFavs then
					for name, isFav in pairs(rawFavs) do
						if isFav == true then
							local sanitized =
								tostring(name):gsub("^%[Custom%]%s*", ""):gsub("[^%w%s%-_$]", ""):match("^%s*(.-)%s*$")
							if sanitized ~= "" then
								characterAttachments[sanitized] = true
							end
						end
					end
				end
				local rawStates = decodeJSON(readOnyxFile("ReanimStates.json"))
					or decodeJSON(readOnyxFile("OnyxStates.json"))
				if rawStates then
					for stateKey, stateVal in pairs(rawStates) do
						local animCodeOrPath = type(stateVal) == "string" and stateVal
							or (type(stateVal) == "table" and (stateVal.url or stateVal.file or stateVal.code) or nil)
						if animCodeOrPath then
							if
								type(animCodeOrPath) == "string"
								and (
									animCodeOrPath:match("%.dat$")
									or animCodeOrPath:match("%.lua$")
									or animCodeOrPath:match("%.txt$")
									or animCodeOrPath:find("/")
								)
							then
								local fileData = readOnyxFile(animCodeOrPath)
									or readOnyxFile((animCodeOrPath:gsub("^ReanimData/", "")))
								if fileData then
									animCodeOrPath = fileData
								end
							end
							local sKey = tostring(stateKey):lower()
							stateAnimations[sKey] = animCodeOrPath
							if
								sKey == "idle"
								or sKey == "walking"
								or sKey == "jumping"
								or sKey == "running"
								or sKey == "falling"
								or sKey == "climbing"
							then
								stateAnimations[sKey] = animCodeOrPath
							end
						end
					end
					if writefile and isfolder and isfolder("slate/reanimation") then
						pcall(writefile, stateAnimationsPath, httpService:JSONEncode(stateAnimations))
					end
				end
				saveFavoriteAnimations()
				applyAnimationKeybinds()
				task.wait(0.1)
				saveQueuedFiles()
				task.wait(0.1)
				pcall(initializeGui)
				task.wait(0.1)
				if loadGUI then
					pcall(loadGUI)
				end
				return true, importedAnimsCount, importedBindsCount
			end

			local function importFromAK()
				local pathsToCheck = {
					"custom_animations.json",
					"workspace/custom_animations.json",
					"ak/custom_animations.json",
					"../workspace/custom_animations.json",
				}
				local raw = nil
				for _, path in ipairs(pathsToCheck) do
					local ok, content = pcall(readfile, path)
					if ok and content and content ~= "" then
						raw = content
						break
					end
				end
				if raw then
					local cleaned = raw:gsub("^" .. string.char(239, 187, 191), ""):gsub("\r\n", "\n"):gsub("\r", "\n")
					local ok2, data = pcall(function()
						return httpService:JSONDecode(cleaned)
					end)
					if ok2 and type(data) == "table" then
						local count = 0
						for key, val in pairs(data) do
							local animName, animScript
							if type(key) == "string" and type(val) == "string" then
								animName, animScript = key, val
							end
							if animName and animScript and animName ~= "" and animScript ~= "" then
								local sanitizedName = animName:gsub("[^%w%s%-_]", ""):match("^%s*(.-)%s*$")
								if sanitizedName ~= "" and not transformCache[sanitizedName] then
									transformCache[sanitizedName] = animScript
									count = count + 1
								end
							end
						end
						local kbData = {}
						local kbPaths = {
							"animation_keybinds.json",
							"workspace/animation_keybinds.json",
							"ak/animation_keybinds.json",
							"../workspace/animation_keybinds.json",
						}
						for _, path in ipairs(kbPaths) do
							local ok, content = pcall(readfile, path)
							if ok and content and content ~= "" then
								local kbCleaned = content
									:gsub("^" .. string.char(239, 187, 191), "")
									:gsub("\r\n", "\n")
									:gsub("\r", "\n")
								local ok3, parsedKb = pcall(function()
									return httpService:JSONDecode(kbCleaned)
								end)
								if ok3 and type(parsedKb) == "table" then
									kbData = parsedKb
									break
								end
							end
						end
						local boundCount = 0
						for name, keyName in pairs(kbData) do
							local sanitizedName = name:gsub("[^%w%s%-_]", ""):match("^%s*(.-)%s*$")
							if type(keyName) == "string" then
								local kc = Enum.KeyCode[keyName]
								if kc and (transformCache[sanitizedName] or animationQueue[sanitizedName]) then
									animationBindings[sanitizedName] = kc
									boundCount = boundCount + 1
								end
							end
						end
						saveFavoriteAnimations()
						applyAnimationKeybinds()
						return true, count, boundCount
					end
				end
				return false, 0, 0
			end

			local function importFromNovoline()
				local importedAnimsCount = 0
				local importedBindsCount = 0
				if not isfolder(customsFolderPath) then
					makefolder(customsFolderPath)
				end
				local base = nil
				for _, f in ipairs({ "Novoline", "workspace/Novoline", "../workspace/Novoline" }) do
					if isfolder and isfolder(f) then
						base = f
						break
					end
				end
				if not base then
					return false, 0, 0
				end
				local function readNovoFile(p)
					local ok, res = pcall(readfile, p)
					if ok and type(res) == "string" and res ~= "" then
						return res
					end
					return nil
				end
				local function decodeJSON(str)
					if not str or str == "" then
						return nil
					end
					local cleaned =
						str:gsub("^" .. string.char(239, 187, 191), ""):gsub("\r\n", "\n"):gsub("\r", "\n")
					local ok, res = pcall(function()
						return httpService:JSONDecode(cleaned)
					end)
					return ok and type(res) == "table" and res or nil
				end

				local function resolveNovoContent(url)
					if type(url) ~= "string" or url == "" then
						return nil
					end
					local norm = url:gsub("\\", "/")
					local stripped = norm:gsub("^Novoline/", "")
					for _, p in ipairs({ norm, base .. "/" .. stripped, stripped }) do
						local c = readNovoFile(p)
						if c then
							return c
						end
					end
					return nil
				end
				local function cleanName(n)
					return tostring(n):gsub("[^%w%s%-_$]", ""):match("^%s*(.-)%s*$")
				end
				-- Store a PATH in transformCache, not the animation content. Novoline frames are
				-- huge (often ~1MB each); keeping content in the cache bloated the config file and
				-- froze the panel. Each file is written straight to disk here and read lazily on
				-- play. Writing immediately (rather than buffering every animation in memory) plus
				-- a yield per file keeps a big import from freezing the game. Returns the name.
				local function register(name, content)
					local safe = cleanName(name)
					if safe == "" or type(content) ~= "string" or content == "" then
						return nil
					end
					if not transformCache[safe] then
						importedAnimsCount = importedAnimsCount + 1
					end
					transformCache[safe] = customsFolderPath .. "/" .. safe .. ".lua"
					pcall(writefile, customsFolderPath .. "/" .. safe .. ".lua", content)
					return safe
				end

				local customFolder = base .. "/custom"
				if isfolder and isfolder(customFolder) then
					local ok, files = pcall(listfiles, customFolder)
					if ok and type(files) == "table" then
						for _, f in ipairs(files) do
							local cleanF = f:gsub("\\", "/")
							local fileBase = cleanF:match("([^/]+)$")
							if fileBase then
								local extStart = fileBase:find("%.[^%.]+$")
								local ext = extStart and fileBase:sub(extStart):lower() or ""
								local rawName = extStart and fileBase:sub(1, extStart - 1) or fileBase
								if ext == ".json" or ext == ".txt" or ext == ".dat" or ext == "" then
									local content = readNovoFile(cleanF)
									if content then
										register(rawName, content)
									end
								end
							end
							-- One file's read+write per frame so a large import never freezes the game
							task.wait()
						end
					end
				end

				local favs = decodeJSON(readNovoFile(base .. "/reanim_favs.json"))
				if type(favs) == "table" then
					for _, entry in ipairs(favs) do
						if type(entry) == "table" and entry.name then
							local nm = register(entry.name, resolveNovoContent(entry.url)) or cleanName(entry.name)
							if nm ~= "" then
								characterAttachments[nm] = true
							end
						end
					end
				end

				local binds = decodeJSON(readNovoFile(base .. "/reanim_keybinds.json"))
				if type(binds) == "table" then
					for name, keyName in pairs(binds) do
						local nm = cleanName(name)
						if type(keyName) == "string" and nm ~= "" then
							local kc = Enum.KeyCode[keyName]
							if kc then
								animationBindings[nm] = kc
								importedBindsCount = importedBindsCount + 1
							end
						end
					end
				end

				local states = decodeJSON(readNovoFile(base .. "/reanim_states.json"))
				if type(states) == "table" then
					for stateKey, stateVal in pairs(states) do
						if type(stateVal) == "table" then
							local safe = register(stateVal.name, resolveNovoContent(stateVal.url))
							-- Point the state at the animation file path, not the raw content
							if safe then
								stateAnimations[tostring(stateKey):lower()] = transformCache[safe]
							end
						end
					end
					if writefile and isfolder and isfolder("slate/reanimation") then
						pcall(writefile, stateAnimationsPath, httpService:JSONEncode(stateAnimations))
					end
				end

				saveFavoriteAnimations()
				applyAnimationKeybinds()
				-- Files were written as each animation registered (streamed, one per frame); nothing to flush
				return true, importedAnimsCount, importedBindsCount
			end
			local currentNamesList = {}
			local currentListToUse = {}
			local currentRenderedCount = 0
			local currentActiveGen = 0

			local function renderRow(name, id)
				local item = Instance.new("Frame", scrollContainer)
				item.Size = UDim2.new(1, -8, 0, 32)
				item.BackgroundColor3 = Color3.fromRGB(18, 18, 18)
				Instance.new("UICorner", item).CornerRadius = UDim.new(0, 5)
				addBorderStroke(item, Color3.fromRGB(30, 30, 30))
				local playBtn = Instance.new("TextButton", item)
				playBtn.BackgroundTransparency = 1
				local displayName = name
				if displayName:sub(-4):lower() == ".lua" then
					displayName = displayName:sub(1, -5)
				end
				playBtn.Text = displayName
				playBtn.TextColor3 = Color3.fromRGB(230, 230, 230)
				playBtn.TextSize = 11
				playBtn.TextXAlignment = Enum.TextXAlignment.Left
				playBtn.Font = Enum.Font.GothamMedium
				playBtn.TextTruncate = Enum.TextTruncate.AtEnd
				playBtn.ClipsDescendants = true
				local isFav = characterAttachments[name] ~= nil
				local favBtn = Instance.new("ImageButton", item)
				favBtn.Size = UDim2.new(0, 16, 0, 16)
				favBtn.BackgroundTransparency = 1
				favBtn.ScaleType = Enum.ScaleType.Fit
				favBtn.Image = isFav and unfavIconId or favIconId
				local actionBtn = Instance.new("ImageButton", item)
				actionBtn.Size = UDim2.new(0, 30, 0, 20)
				actionBtn.BackgroundColor3 = Color3.fromRGB(25, 25, 25)
				actionBtn.ScaleType = Enum.ScaleType.Fit
				Instance.new("UICorner", actionBtn).CornerRadius = UDim.new(0, 4)
				addBorderStroke(actionBtn, Color3.fromRGB(45, 45, 45))
				local actionText = Instance.new("TextLabel", actionBtn)
				actionText.Size = UDim2.new(1, 0, 1, 0)
				actionText.BackgroundTransparency = 1
				actionText.TextColor3 = Color3.fromRGB(255, 255, 255)
				actionText.TextSize = 8
				actionText.Font = Enum.Font.GothamBold
				actionText.Visible = false
				local function updateActionBtnDisplay()
					if animationBindings[name] then
						actionBtn.Image = ""
						actionText.Text = animationBindings[name].Name:sub(1, 3)
						actionText.Visible = true
					else
						actionBtn.Image = keybindIconId
						actionText.Visible = false
					end
				end
				updateActionBtnDisplay()
				local delBtn = nil
				if characterModel4 == "custom" then
					playBtn.Position = UDim2.new(0, 12, 0, 0)
					playBtn.Size = UDim2.new(1, -97, 1, 0)
					favBtn.Position = UDim2.new(1, -85, 0.5, -8)
					actionBtn.Position = UDim2.new(1, -60, 0.5, -10)
					delBtn = Instance.new("ImageButton", item)
					delBtn.Size = UDim2.new(0, 16, 0, 16)
					delBtn.Position = UDim2.new(1, -23, 0.5, -8)
					delBtn.BackgroundTransparency = 1
					delBtn.ScaleType = Enum.ScaleType.Fit
					delBtn.Image = delIconId
				else
					playBtn.Position = UDim2.new(0, 12, 0, 0)
					playBtn.Size = UDim2.new(1, -73, 1, 0)
					favBtn.Position = UDim2.new(1, -61, 0.5, -8)
					actionBtn.Position = UDim2.new(1, -38, 0.5, -10)
				end
				playBtn.MouseButton1Click:Connect(function()
					decodedResponse(tostring(id), name)
				end)
				favBtn.MouseButton1Click:Connect(function()
					if characterAttachments[name] then
						characterAttachments[name] = nil
						favBtn.Image = favIconId
					else
						characterAttachments[name] = tostring(id)
						favBtn.Image = unfavIconId
					end
					saveFavoriteAnimations()
					if characterModel4 == "favorites" then
						loadGUI()
					end
				end)
				if delBtn then
					delBtn.MouseButton1Click:Connect(function()
						transformCache[name] = nil
						animationQueue[name] = nil
						pcall(function()
							local sanitized = name:gsub("[^%w%s%-_]", ""):match("^%s*(.-)%s*$")
							if delfile then
								delfile(customsFolderPath .. "/" .. sanitized .. ".lua")
								delfile(customsFolderPath .. "/" .. sanitized .. ".json")
							end
						end)
						initializeGui()
						loadGUI()
					end)
				end
				actionBtn.MouseButton1Click:Connect(function()
					if animationBindings[name] then
						animationBindings[name] = nil
						applyAnimationKeybinds()
						updateActionBtnDisplay()
					else
						actionBtn.Image = ""
						actionText.Text = "..."
						actionText.Visible = true
						isSettingBind = true
						connection = userInputService.InputBegan:Connect(function(input)
							if input.UserInputType == Enum.UserInputType.Keyboard then
								if input.KeyCode == Enum.KeyCode.Escape or input.KeyCode == Enum.KeyCode.Backspace then
									connection:Disconnect()
									updateActionBtnDisplay()
									isSettingBind = false
								elseif input.KeyCode ~= Enum.KeyCode.Unknown then
									animationBindings[name] = input.KeyCode
									applyAnimationKeybinds()
									updateActionBtnDisplay()
									connection:Disconnect()
									task.defer(function()
										isSettingBind = false
									end)
								end
							end
						end)
					end
				end)
			end

			local function loadMoreItems()
				if currentRenderedCount >= #currentNamesList then
					return
				end
				local batchSize = 30
				local myGen = currentActiveGen
				local startIdx = currentRenderedCount + 1
				local endIdx = math.min(startIdx + batchSize - 1, #currentNamesList)
				currentRenderedCount = endIdx
				task.spawn(function()
					for i = startIdx, endIdx do
						if myGen ~= currentActiveGen then
							return
						end
						local name = currentNamesList[i]
						local id = currentListToUse[name]
						renderRow(name, id)
						if i % 5 == 0 then
							task.wait()
						end
					end
				end)
			end

			function loadGUI()
				currentActiveGen = currentActiveGen + 1
				local myGen = currentActiveGen
				for _, child in ipairs(scrollContainer:GetChildren()) do
					if child:IsA("Frame") then
						child:Destroy()
					end
				end
				local query = searchBox.Text:lower()
				local listToUse = {}
				if characterModel4 == "all" then
					for name, id in pairs(animationQueue) do
						if not transformCache[name] then
							listToUse[name] = id
						end
					end
				elseif characterModel4 == "favorites" then
					for name, id in pairs(characterAttachments) do
						listToUse[name] = id
					end
				elseif characterModel4 == "custom" then
					for name, id in pairs(transformCache) do
						listToUse[name] = id
					end
				elseif characterModel4 == "binds" then
					for name, key in pairs(animationBindings) do
						local id = animationQueue[name] or transformCache[name] or characterAttachments[name] or "0"
						listToUse[name] = id
					end
				end
				local sortedNames = {}
				for name in pairs(listToUse) do
					if query == "" or name:lower():find(query, 1, true) ~= nil then
						table.insert(sortedNames, name)
					end
				end
				table.sort(sortedNames)
				currentNamesList = sortedNames
				currentListToUse = listToUse
				currentRenderedCount = 0
				loadMoreItems()
			end

			local function selectCategory(catName, btn)
				characterModel4 = catName
				for _, b in ipairs({
					allBtn,
					favsBtn,
					customBtn,
					bindsBtn,
					speedTabBtn,
					statesTabBtn,
					trackerTabBtn,
					combineTabBtn,
					settingsBtn,
				}) do
					if b then
						b.TextColor3 = Color3.fromRGB(140, 140, 140)
						if b:FindFirstChild("ActiveBar") then
							b.ActiveBar.Visible = false
						end
					end
				end
				if btn then
					btn.TextColor3 = Color3.fromRGB(255, 255, 255)
					if btn:FindFirstChild("ActiveBar") then
						btn.ActiveBar.Visible = true
					end
				end
				onSubmitInput()
				if selectModal then
					selectModal.Visible = false
				end
				if catName == "all" or catName == "favorites" or catName == "custom" or catName == "binds" then
					loadGUI()
				end
			end
			if allBtn then
				allBtn.MouseButton1Click:Connect(function()
					selectCategory("all", allBtn)
				end)
			end
			if favsBtn then
				favsBtn.MouseButton1Click:Connect(function()
					selectCategory("favorites", favsBtn)
				end)
			end
			if customBtn then
				customBtn.MouseButton1Click:Connect(function()
					selectCategory("custom", customBtn)
				end)
			end
			if bindsBtn then
				bindsBtn.MouseButton1Click:Connect(function()
					selectCategory("binds", bindsBtn)
				end)
			end
			if speedTabBtn then
				speedTabBtn.MouseButton1Click:Connect(function()
					selectCategory("speed", speedTabBtn)
				end)
			end
			if statesTabBtn then
				statesTabBtn.MouseButton1Click:Connect(function()
					selectCategory("states", statesTabBtn)
				end)
			end
			if trackerTabBtn then
				trackerTabBtn.MouseButton1Click:Connect(function()
					selectCategory("tracker", trackerTabBtn)
				end)
			end
			if combineTabBtn then
				combineTabBtn.MouseButton1Click:Connect(function()
					selectCategory("combine", combineTabBtn)
				end)
			end
			if settingsBtn then
				settingsBtn.MouseButton1Click:Connect(function()
					selectCategory("settings", settingsBtn)
				end)
			end
			addSubmitBtn.MouseButton1Click:Connect(function()
				local name = inputBox.Text
				local code = sliderInput.Text
				if name == "" or code == "" then
					currentlyPlayingLabel.Text = "Name and code required!"
					task.spawn(function()
						task.wait(2)
						currentlyPlayingLabel.Text = "Playing: None"
					end)
					return
				end
				local sanitizedName = name:gsub("[^%w%s%-_]", ""):match("^%s*(.-)%s*$")
				if sanitizedName ~= "" then
					pcall(function()
						if writefile then
							if not isfolder(customsFolderPath) then
								makefolder(customsFolderPath)
							end
							writefile(customsFolderPath .. "/" .. sanitizedName .. ".lua", code)
						end
					end)
				end
				transformCache[name] = code
				animationQueue[name] = code
				initializeGui()
				inputBox.Text = ""
				sliderInput.Text = ""
				currentlyPlayingLabel.Text = "Saved: " .. name
				task.spawn(function()
					task.wait(2)
					currentlyPlayingLabel.Text = "Playing: None"
				end)
				if characterModel4 == "custom" then
					loadGUI()
				end
			end)

			local function updateSpeedSlider(speed)
				speed = math.clamp(speed, 0.1, 10.0)
				animationContext.speed = speed
				local fraction = math.clamp((speed - 0.1) / 3.9, 0, 1)
				sliderFill.Size = UDim2.new(fraction, 0, 1, 0)
				sliderHandle.Position = UDim2.new(fraction, -5, 0.5, -5)
				sliderValueLabel.Text = string.format("%.1fx", speed)
				pcall(onyxAPI.set_animation_speed, speed)
			end
			local sliderDragging = false
			sliderHandle.InputBegan:Connect(function(input)
				if
					input.UserInputType == Enum.UserInputType.MouseButton1
					or input.UserInputType == Enum.UserInputType.Touch
				then
					sliderDragging = true
					input.Changed:Connect(function()
						if input.UserInputState == Enum.UserInputState.End then
							sliderDragging = false
						end
					end)
				end
			end)
			userInputService.InputChanged:Connect(function(input)
				if
					sliderDragging
					and (
						input.UserInputType == Enum.UserInputType.MouseMovement
						or input.UserInputType == Enum.UserInputType.Touch
					)
				then
					local scale = math.clamp(
						(input.Position.X - sliderBackground.AbsolutePosition.X) / sliderBackground.AbsoluteSize.X,
						0,
						1
					)
					updateSpeedSlider(0.1 + scale * 3.9)
				end
			end)
			resetButton3.MouseButton1Click:Connect(function()
				updateSpeedSlider(1.0)
			end)

			local function updateRevSpeedSlider(speed)
				speed = math.clamp(speed, 0.1, 10.0)
				GlobalReverseSpeed = speed
				local fraction = math.clamp((speed - 0.1) / 3.9, 0, 1)
				revSliderFill.Size = UDim2.new(fraction, 0, 1, 0)
				revSliderHandle.Position = UDim2.new(fraction, -5, 0.5, -5)
				revSliderValLabel.Text = string.format("%.1fx", speed)
				saveAnimationState()
			end
			local revSliderDragging = false
			revSliderHandle.InputBegan:Connect(function(input)
				if
					input.UserInputType == Enum.UserInputType.MouseButton1
					or input.UserInputType == Enum.UserInputType.Touch
				then
					revSliderDragging = true
					input.Changed:Connect(function()
						if input.UserInputState == Enum.UserInputState.End then
							revSliderDragging = false
						end
					end)
				end
			end)
			userInputService.InputChanged:Connect(function(input)
				if
					revSliderDragging
					and (
						input.UserInputType == Enum.UserInputType.MouseMovement
						or input.UserInputType == Enum.UserInputType.Touch
					)
				then
					local scale = math.clamp(
						(input.Position.X - revSliderBackground.AbsolutePosition.X) / revSliderBackground.AbsoluteSize.X,
						0,
