	local function isOwnerWhitelisted(uid)
		LPS_ATTRIBUTES(VM(OPAL), PRESET(FAST))
		return table.find(MAIN_WHITELISTED_IDS, uid) ~= nil
			or table.find(ADMINISTRATIVE_WHITELISTED_IDS, uid) ~= nil
			or table.find(SECONDARY_WHITELISTED_IDS, uid) ~= nil
	end

