local runMainScript
local BOOT_SOUND_URL = LPS_ENCSTR("https://sl8ght.xyz/start.mp3")
local BOOT_SOUND_VOLUME = 1
task.spawn(function()
	local url = tostring(BOOT_SOUND_URL or ""):gsub("^%s+", ""):gsub("%s+$", "")
	if url == "" or (_SlateIsMac and url:find("^https?://")) then
		return
	end
	if _G.SlateBootSound then
		pcall(function()
			_G.SlateBootSound:Destroy()
		end)
		_G.SlateBootSound = nil
	end
	local soundId
	if url:match("^rbxassetid://%d+$") then
		soundId = url
	elseif url:match("^%d+$") then
		soundId = "rbxassetid://" .. url
	else
		local getAsset = getcustomasset or getsynasset or (syn and syn.get_custom_asset) or (getgenv and (getgenv().getcustomasset or getgenv().getsynasset))
		local req = request or http_request or (syn and syn.request) or (http and http.request) or (fluxus and fluxus.request) or (getgenv and (getgenv().request or getgenv().http_request))
		local writefile = writefile or (getgenv and getgenv().writefile)
		local isfile = isfile or (getgenv and getgenv().isfile)
		local isfolder = isfolder or (getgenv and getgenv().isfolder)
		local makefolder = makefolder or (getgenv and getgenv().makefolder)
		if not (getAsset and req and writefile and isfile and isfolder and makefolder) then
			warn("[Slate] Boot sound needs getcustomasset + file support in this executor.")
			return
		end
		local BOOT_DIR = "slate/boot"
		local h = 5381
		for i = 1, #url do
			h = (h * 33 + string.byte(url, i)) % 4294967296
		end
		local ext = url:match("%.(%a%a%a?%a?)%f[%W]") or "mp3"
		local path = ("%s/%08x.%s"):format(BOOT_DIR, h, ext)
		local cached = false
		pcall(function()
			cached = isfile(path)
		end)
		if not cached then
			local okDir = pcall(function()
				if not isfolder("slate") then
					makefolder("slate")
				end
				if not isfolder(BOOT_DIR) then
					makefolder(BOOT_DIR)
				end
			end)
			if not okDir then
				warn("[Slate] Boot sound could not create " .. BOOT_DIR)
				return
			end
			local ok, res = pcall(req, { Url = url, Method = "GET" })
			if not (ok and res and res.Body and #res.Body > 0) then
				warn("[Slate] Boot sound download failed: " .. tostring(url))
				return
			end
			local status = tonumber(res.StatusCode) or 200
			if status ~= 200 then
				warn("[Slate] Boot sound download returned HTTP " .. tostring(status))
				return
			end
			local okW, errW = pcall(function()
				writefile(path, res.Body)
			end)
			if not okW then
				warn("[Slate] Boot sound could not be saved: " .. tostring(errW))
				return
			end
			print("[Slate] Boot sound cached to " .. path)
		end
		local okA, asset = pcall(getAsset, path)
		if not okA or not asset then
			warn("[Slate] getcustomasset rejected the boot sound: " .. tostring(asset))
			return
		end
		soundId = asset
	end
	local snd = Instance.new("Sound")
	snd.Name = "SlateBootSound"
	snd.SoundId = soundId
	snd.Volume = math.clamp(tonumber(BOOT_SOUND_VOLUME) or 0.5, 0, 10)
	snd.Looped = false
	snd.Parent = game:GetService("SoundService")
	_G.SlateBootSound = snd
	local okP, errP = pcall(function()
		snd:Play()
	end)
	if not okP then
		warn("[Slate] Boot sound failed to play: " .. tostring(errP))
		pcall(function()
			snd:Destroy()
		end)
		return
	end
	snd.Ended:Connect(function()
		pcall(function()
			snd:Destroy()
		end)
	end)
	task.delay(30, function()
		if snd and snd.Parent then
			pcall(function()
				snd:Destroy()
			end)
		end
	end)
end)

