-- Slate Reanimate: Lazy-loaded on demand (when ;reanim is run or onyxAPI is needed)
local _reanimLoading = false
local _reanimLoaded = false
function Slate.ensureReanimateLoaded(onComplete)
	if _reanimLoaded and _G.onyxAPI then
		if onComplete then onComplete(_G.onyxAPI) end
		return _G.onyxAPI
	end
	if _reanimLoading then
		if onComplete then
			task.spawn(function()
				while _reanimLoading do task.wait(0.05) end
				if onComplete then onComplete(_G.onyxAPI) end
			end)
		end
		return nil
	end
	_reanimLoading = true
	local ok, err = pcall(Slate.reanimate)
	if not ok then
		warn("[Slate Reanimate] Failed to lazy load: " .. tostring(err))
		pcall(function()
			if isfile and isfile("slate/reanimate.lua") then
				loadstring(readfile("slate/reanimate.lua"))()
			elseif isfile and isfile("reanimate.lua") then
				loadstring(readfile("reanimate.lua"))()
			end
		end)
	end
	_reanimLoaded = true
	_reanimLoading = false
	Slate._slateReanimDone = true
	if onComplete then onComplete(_G.onyxAPI) end
	return _G.onyxAPI
end
_G.ensureReanimateLoaded = Slate.ensureReanimateLoaded
Slate._slateReanimDone = true
