	function SlateNav.paintRow(rec)
		if rec.hovering then
			return
		end
		local active = rec.isActive and rec.isActive() or false
		tweenService
			:Create(rec.row, TweenInfo.new(0.16, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
				Size = rec.baseSize,
				Position = rec.basePos,
				BackgroundTransparency = active and 0.9 or 1,
			})
			:Play()
		tweenService
			:Create(rec.icon, TweenInfo.new(0.16), {
				Size = UDim2.new(0, 24, 0, 24),
				ImageColor3 = active and Color3.fromRGB(255, 255, 255) or Color3.fromRGB(150, 150, 158),
			})
			:Play()
		rec.icon.Position = UDim2.new(0, 14, 0.5, -12)
		tweenService
			:Create(rec.label, TweenInfo.new(0.16), {
				TextColor3 = active and Color3.fromRGB(255, 255, 255) or Color3.fromRGB(160, 160, 168),
			})
			:Play()
		rec.label.Font = active and Enum.Font.BuilderSansBold or Enum.Font.BuilderSans
	end

	function SlateNav.paint()
		for _, rec in ipairs(SlateNav.rows) do
			pcall(SlateNav.paintRow, rec)
		end
	end

	function switchTab(tab)
		if not tab then
			return
		end
		local main = G2L and G2L["2"]
		if main then
			for _, child in ipairs(main:GetChildren()) do
				if child:IsA("CanvasGroup") or child:IsA("Frame") then
					if
						child ~= tab
						and child.Name ~= "HeaderBar"
						and child.Name ~= "Backdrop"
						and child.Name ~= "SlateBackdrop"
						and not child.Name:find("Sidebar")
						and not child.Name:find("Nav")
					then
						child.Visible = false
						if child:IsA("CanvasGroup") then
							child.GroupTransparency = 1
						end
					end
				end
			end
		end
		activeTab = tab
		tab.Visible = true
		tab.ZIndex = 2
		if not main or not main.Visible or main.GroupTransparency > 0.9 then
			tab.GroupTransparency = 0
			if main then
				main.Visible = true
				main.GroupTransparency = 1
				tweenService
					:Create(
						main,
						TweenInfo.new(0.25, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
						{ GroupTransparency = 0 }
					)
					:Play()
			end
			showBlurOverlay()
			if SlateNav and SlateNav.paint then
				task.defer(SlateNav.paint)
			end
			return
		end
		if SlateNav and SlateNav.paint then
			task.defer(SlateNav.paint)
		end
		if tab.GroupTransparency > 0 then
			tweenService
				:Create(
					tab,
					TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
					{ GroupTransparency = 0 }
				)
				:Play()
		end
	end

	function toggleMainWindow()
		local main = G2L and G2L["2"]
		if not main then
			return
		end
		if main.Visible and main.GroupTransparency < 0.1 then
			local fade = tweenService:Create(
				main,
				TweenInfo.new(0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
				{ GroupTransparency = 1 }
			)
			fade.Completed:Connect(function()
				main.Visible = false
			end)
			fade:Play()
			pcall(hideBlurOverlay)
			return false
		end
		pcall(SlateNav.build)
		local target = activeTab or (G2L and G2L["6"])
		if target then
			switchTab(target)
		else
			main.Visible = true
			main.GroupTransparency = 1
			tweenService
				:Create(
					main,
					TweenInfo.new(0.25, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
					{ GroupTransparency = 0 }
				)
				:Play()
			pcall(showBlurOverlay)
		end
		pcall(SlateNav.paint)
		return true
	end
	_G.SlateToggleUI = toggleMainWindow

	function toggleWindow(win)
		if win.Visible and win.GroupTransparency < 0.1 then
			local fade = tweenService:Create(
				win,
				TweenInfo.new(0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
				{ GroupTransparency = 1 }
			)
			fade.Completed:Connect(function()
				win.Visible = false
			end)
			fade:Play()
		else
			win.Visible = true
			win.GroupTransparency = 1
			tweenService
				:Create(
					win,
					TweenInfo.new(0.25, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
					{ GroupTransparency = 0 }
				)
				:Play()
		end
	end

	function addLabel(parent, text, size, pos, isTitle)
		local lbl = Instance.new("TextLabel")
		lbl.BorderSizePixel = 0
		lbl.BackgroundTransparency = 1
		lbl.TextColor3 = Color3.fromRGB(255, 255, 255)
		lbl.TextXAlignment = Enum.TextXAlignment.Left
		lbl.TextSize = isTitle and 22 or 14
		lbl.FontFace = Font.new(
			"rbxasset://fonts/families/SourceSansPro.json",
			isTitle and Enum.FontWeight.Bold or Enum.FontWeight.Regular,
			Enum.FontStyle.Normal
		)
		lbl.Size = size
		lbl.Position = pos
		lbl.Text = text
		lbl.Parent = parent
		if not isTitle then
			lbl.TextTransparency = 0.4
		end
		return lbl
	end
