	local function readServerPing()
		local ok, value = pcall(function()
			return game:GetService("Stats").Network.ServerToClientPing:GetValue()
		end)
		if ok and tonumber(value) then
			return math.floor(tonumber(value) + 0.5)
		end
		local ok2, value2 = pcall(function()
			return localPlayer:GetNetworkPing() * 1000
		end)
		if ok2 and tonumber(value2) then
			return math.floor(tonumber(value2) + 0.5)
		end
		return nil
	end

