		end)
		pcall(function()
			local playersCount = #players:GetPlayers()
			local maxPlayers = players.MaxPlayers
			ServerPlayersLbl.Text = "Players: " .. tostring(playersCount) .. "/" .. tostring(maxPlayers)
		end)
	end
