					if type(t) ~= "table" then
						return 0
					end
					local c = 0
					for _ in pairs(t) do
						c = c + 1
					end
					return c
				end
				local function normalizeUserList(users)
					if type(users) ~= "table" then
						return {}
					end
					local arr = {}
					for _, uid in pairs(users) do
						local numUid = tonumber(uid) or uid
						if numUid then
							arr[#arr + 1] = numUid
						end
					end
					return arr
				end
				local function fetchGlobalUsersPayload()
					local base = (
						_G.SlateBackendBase
						or (getgenv and getgenv().BACKEND_URL)
						or _G.BACKEND_URL
						or (getgenv and getgenv().SLATE_BACKEND)
						or _G.SLATE_BACKEND
						or "https://sl8ght.xyz"
					):gsub("/+$", "")
					local endpoints = {
						base .. LPS_ENCSTR("/api/globalusers"),
						"https://sl8ght.xyz/api/globalusers",
						"https://sl8ght.xyz/api/globalusers",
					}
					local reqFunc = (type(request) == "function" and request)
						or (type(http_request) == "function" and http_request)
						or (type(syn) == "table" and type(syn.request) == "function" and syn.request)
						or (type(fluxus) == "table" and type(fluxus.request) == "function" and fluxus.request)
						or (type(http) == "table" and type(http.request) == "function" and http.request)
					local rawJson = nil
					if reqFunc then
						for _, url in ipairs(endpoints) do
							local ok, res = pcall(reqFunc, {
								Url = url,
								Method = "GET",
								Headers = {
									["User-Agent"] = "SlateClient/1.0",
									["Accept"] = "application/json",
								},
							})
							if
								ok
								and res
								and (res.StatusCode == 200 or res.Status == 200)
								and res.Body
								and #res.Body > 0
							then
								rawJson = res.Body
								break
							end
						end
					end
					if not rawJson and type(game.HttpGet) == "function" then
						for _, url in ipairs(endpoints) do
							local ok, body = pcall(game.HttpGet, game, url)
							if ok and body and #body > 0 then
								rawJson = body
								break
							end
						end
					end
					if not rawJson then
						return nil
					end
					local hs = game:GetService("HttpService")
					local ok, data = pcall(function()
						return hs:JSONDecode(rawJson)
					end)
					if ok and type(data) == "table" and type(data.servers) == "table" then
						return data
					end
					return nil
