							:Play()
						tweenService
							:Create(strk, TweenInfo.new(0.15), {
								Color = Color3.fromRGB(30, 30, 36),
							})
							:Play()
					end
				end)
			end
			attachHover(btn1, stroke1, 1)
			attachHover(btn2, stroke2, 2)
			attachHover(btn3, stroke3, 3)
