					isScrubbingDeck = true
					_G.SlateIsScrubbing = true
					tweenService
						:Create(
							deckProgKnob,
							TweenInfo.new(0.18, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
							{ Size = UDim2.new(0, 18, 0, 18), BackgroundTransparency = 0.45 }
						)
						:Play()
					tweenService
						:Create(
							deckProgStroke,
							TweenInfo.new(0.18, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
							{ Transparency = 0.1, Thickness = 1.8 }
						)
						:Play()
					local pct = updateDeckScrub(input)
					local total = _G.SlateMusicTotalDuration or 0
					if total > 0 and Slate.SlateMusicSeek then
						Slate.SlateMusicSeek(pct * total)
					end
				end
			end)
