			local currentSearchGen = 0
			local lastSearchQuery = ""
			local searchTimerThread = nil
			local function performLiveSearch(q)
				q = (q or ""):gsub("^%s+", ""):gsub("%s+$", "")
				if q == lastSearchQuery then
					return
				end
				lastSearchQuery = q
				if q == "" then
					for _, section in ipairs({ ArtistSection, SongSection }) do
						for _, child in ipairs(section:GetChildren()) do
							if child:IsA("Frame") or child:IsA("TextLabel") then
								child:Destroy()
							end
						end
					end
					return
				end
				currentSearchGen = currentSearchGen + 1
				local thisGen = currentSearchGen
				if Slate.SlateMusicSearchArtists then
					Slate.SlateMusicSearchArtists(q, function(artists)
						if thisGen == currentSearchGen and Slate.SlateRenderMusicArtists then
							Slate.SlateRenderMusicArtists(artists, thisGen)
						end
					end)
				end
				if Slate.SlateMusicSearch then
					Slate.SlateMusicSearch(q, function(tracks)
						if thisGen == currentSearchGen and Slate.SlateRenderMusicResults then
							Slate.SlateRenderMusicResults(tracks, thisGen)
						end
					end)
				end
			end
			MusicSearchBar.FocusLost:Connect(function()
				performLiveSearch(MusicSearchBar.Text)
			end)
			MusicSortBtn.MouseButton1Click:Connect(function()
				sortModeIndex = (sortModeIndex % #SortModes) + 1
				local mode = SortModes[sortModeIndex]
				MusicSortBtn.Text = mode.label
				if Slate.SlateMusicSetSearchSort then
					Slate.SlateMusicSetSearchSort(mode.key)
				end
				local existing = Slate.SlateMusicGetLastResults and Slate.SlateMusicGetLastResults() or nil
				if existing and #existing > 0 and Slate.SlateRenderMusicResults then
					Slate.SlateRenderMusicResults(existing, currentSearchGen)
				end
			end)
			MusicSearchBar:GetPropertyChangedSignal("Text"):Connect(function()
				local txt = MusicSearchBar.Text
				if searchTimerThread then
