				if
					input.UserInputType ~= Enum.UserInputType.MouseMovement
					and input.UserInputType ~= Enum.UserInputType.Touch
				then
					return
				end
				local dx, dy = input.Position.X - orbGrab.X, input.Position.Y - orbGrab.Y
				if not orbMoved and (math.abs(dx) > ORB_SLOP or math.abs(dy) > ORB_SLOP) then
					orbMoved = true
				end
				if orbMoved then
					espOrb.Position =
						clampToViewport(UDim2.new(0, orbFrom.X.Offset + dx, 0, orbFrom.Y.Offset + dy), ORB, ORB)
				end
			end)
