Slate.SlateMusicCreatePlaylist = function(name)
	if not name or name == "" then
		return
	end
	SlateMusic.playlists[name] = SlateMusic.playlists[name] or {}
	SlateMusic.savePlaylists()
end
Slate.SlateMusicDeletePlaylist = function(name)
	if not name or name == "Favorites" then
		return
	end
	SlateMusic.playlists[name] = nil
	if SlateMusic.playlistMeta then
		SlateMusic.playlistMeta[name] = nil
	end
	SlateMusic.savePlaylists()
end
Slate.SlateMusicRemoveFromPlaylist = function(playlistName, trackId)
	if not playlistName or not SlateMusic.playlists[playlistName] then
		return
	end
	local list = SlateMusic.playlists[playlistName]
	for i, trk in ipairs(list) do
		if trk.id == trackId then
			table.remove(list, i)
			break
		end
	end
	SlateMusic.playlists[playlistName] = list
	SlateMusic.savePlaylists()
end
Slate.SlateMusicAddToPlaylist = function(playlistName, track)
	if not playlistName or not track or not SlateMusic.playlists[playlistName] then
		return false
	end
	for _, trk in ipairs(SlateMusic.playlists[playlistName]) do
		if trk.id == track.id then
			return false
		end
	end
	table.insert(SlateMusic.playlists[playlistName], track)
	SlateMusic.savePlaylists()
	return true
end
Slate.SlateMusicSeek = function(posSec)
	SlateMusic.seek(posSec)
