_IY_getPlayersByName = function(name)
	local name_l = tostring(name or ""):lower()
	local found = {}
	for _, v in ipairs(_IY_Players_Raw:GetPlayers()) do
		if v.Name:lower():sub(1, #name_l) == name_l or v.DisplayName:lower():sub(1, #name_l) == name_l then
