local function _slateBridgeCommandEnv()
	local envs, seen = {}, {}
	local function addEnv(env)
		if type(env) == "table" and not seen[env] then
			seen[env] = true
			envs[#envs + 1] = env
		end
	end
	local commandEnv
	pcall(function()
		commandEnv = getfenv and getfenv(Slate.commands) or nil
		addEnv(commandEnv)
	end)
	if type(commandEnv) == "table" and commandEnv ~= _SE then
		for key, value in pairs(commandEnv) do
			if rawget(_SE, key) == nil then
				rawset(_SE, key, value)
			end
		end
	end
	pcall(function() addEnv(getfenv and getfenv(1)) end)
	pcall(function() addEnv(getgenv and getgenv()) end)
	addEnv(_G)
	addEnv(_SE)
	local names = {
		"addcmd", "removecmd", "overridecmd", "addbind", "execCmd", "cmds", "CMDs", "PARENT", "IsOnMobile",
		"notify", "getRoot", "r15", "getstring", "isNumber", "vtype", "Scale", "ScaledHolder", "aliases",
		"FindPlugins", "PluginsTable", "spawnCmds", "Credits", "Logo", "Cmdbar", "Holder", "guiScale",
		"maximizeHolder", "minimizeHolder", "shade1", "shade2", "shade3", "text1", "text2", "currentShade1",
		"currentShade2", "currentShade3", "currentText1", "currentText2", "currentScroll", "ChatLog", "JoinLog",
		"avatarcache", "eventEditor", "loadedEventData", "CaptureService", "IntroBackground", "AvatarEditorService",
		"CreateLabel", "sendChatWebhook", "updatesaves", "customAlias", "refreshaliases", "IYMouse", "checkTT", "updateColors", "isLegacyChat",
		"currentVersion", "iygetcustomasset", "Clip", "FLYING", "ESPenabled", "ESP", "CHMSenabled", "CHMS",
		"TextChatService", "logsEnabled", "tools", "SlateBinds", "onyxCommands", "onyxAliases", "_IY_execCmd"
	}
	for _, name in ipairs(names) do
		if _SE[name] == nil then
			for _, env in ipairs(envs) do
				local value = rawget(env, name)
				if value ~= nil then
					_SE[name] = value
					break
				end
			end
		end
	end
end
