					cmdName = _SE.onyxAliases[cmdName] or cmdName
					for _, cmd in ipairs(_SE.onyxCommands) do
						if cmd.name == cmdName then
							if cmd.isToggle then
								local newState = not cmd.getState()
								cmd.callback(newState)
