	local buildFavsList
	do
		local p = Instance.new("Frame", scrollContainer)
		p.Size = UDim2.new(1, 0, 1, 0)
		p.BackgroundTransparency = 1
		p.Visible = true
		pages["Emotes"] = p
		local listL = Instance.new("UIListLayout", p)
		listL.Padding = UDim.new(0, 5)
		listL.SortOrder = Enum.SortOrder.LayoutOrder
		local currentRenderToken = 0
		local loadedIndex = 0
		local filteredSource = {}

		local function prepareSource(filter)
			filteredSource = {}
			filter = filter:lower()
			if _rawCatalog and type(_rawCatalog) == "table" then
				for idx, item in ipairs(_rawCatalog) do
					if type(item) == "table" then
						local id = tostring(item.id or item.idStr or item.assetId or item.AssetId or "")
						local name = tostring(item.name or item.Name or "Unknown")
						if id ~= "" and tonumber(id) then
							if filter == "" or name:lower():find(filter, 1, true) then
								table.insert(filteredSource, { id = id, name = name })
							end
						end
					end
				end
			else
				for _, em in ipairs(EMOTES) do
					if filter == "" or em.name:lower():find(filter, 1, true) then
						table.insert(filteredSource, em)
					end
				end
			end
		end

		local function renderMoreRows(batchSize)
			batchSize = batchSize or 30
			local target = math.min(#filteredSource, loadedIndex + batchSize)
			for i = loadedIndex + 1, target do
				loadedIndex = i
				renderEmoteRow(p, filteredSource[i], loadedIndex, function()
					if buildFavsList then
						buildFavsList(searchBox.Text)
					end
				end)
			end
		end

		local function buildEmotesList(filter)
			currentRenderToken = currentRenderToken + 1
			for _, c in ipairs(p:GetChildren()) do
				if c:IsA("Frame") then
					c:Destroy()
				end
			end
			loadedIndex = 0
			prepareSource(filter)
			renderMoreRows(40)
			updateTabCounts()
		end
		scrollContainer:GetPropertyChangedSignal("CanvasPosition"):Connect(function()
			if pages["Emotes"].Visible and filteredSource then
				local maxScroll = scrollContainer.AbsoluteCanvasSize.Y - scrollContainer.AbsoluteWindowSize.Y
				if maxScroll > 0 and scrollContainer.CanvasPosition.Y >= maxScroll - 150 then
					if loadedIndex < #filteredSource then
						renderMoreRows(30)
					end
				end
			end
		end)
		buildEmotesList("")
		_buildEmotesListCallback = function()
			buildEmotesList(searchBox.Text)
		end
		searchBox:GetPropertyChangedSignal("Text"):Connect(function()
			buildEmotesList(searchBox.Text)
		end)
	end
	do
		local p = Instance.new("Frame", scrollContainer)
		p.Size = UDim2.new(1, 0, 1, 0)
		p.BackgroundTransparency = 1
		p.Visible = false
		pages["Favorites"] = p
		local listL = Instance.new("UIListLayout", p)
		listL.Padding = UDim.new(0, 5)
		listL.SortOrder = Enum.SortOrder.LayoutOrder
		buildFavsList = function(filter)
			for _, c in ipairs(p:GetChildren()) do
				if c:IsA("Frame") then
					c:Destroy()
				end
			end
			local idx = 0
			for _, em in ipairs(EMOTES) do
				if emoteFavorites[tostring(em.id)] then
					if not filter or filter == "" or em.name:lower():find(filter:lower(), 1, true) then
						idx = idx + 1
						renderEmoteRow(p, em, idx, function()
							buildFavsList(filter)
						end)
					end
				end
			end
			if idx == 0 then
				local noFavsLbl = Instance.new("TextLabel", p)
				noFavsLbl.Size = UDim2.new(1, 0, 0, 32)
				noFavsLbl.BackgroundTransparency = 1
				noFavsLbl.Text = "No favorites yet \u{2014} star an emote!"
				noFavsLbl.TextColor3 = Color3.fromRGB(120, 120, 120)
				noFavsLbl.TextSize = 11
				noFavsLbl.Font = Enum.Font.GothamMedium
			end
			updateTabCounts()
		end
		buildFavsList("")
	end
	do
		local p = Instance.new("Frame", scrollContainer)
		p.Size = UDim2.new(1, 0, 1, 0)
		p.BackgroundTransparency = 1
		p.Visible = false
		pages["Packs"] = p
		local listL = Instance.new("UIListLayout", p)
		listL.Padding = UDim.new(0, 6)
		listL.SortOrder = Enum.SortOrder.LayoutOrder

		local function rebuildPacksList(filter)
			for _, child in ipairs(p:GetChildren()) do
				if child:IsA("Frame") then
					child:Destroy()
				end
			end
			filter = (filter or ""):lower()
			local idx = 0
			for _, packName in ipairs(PACK_NAMES) do
				local packTitle = packName .. " Pack"
				if filter == "" or packTitle:lower():find(filter, 1, true) then
					idx = idx + 1
					local row = Instance.new("Frame", p)
					row.Size = UDim2.new(1, -8, 0, 46)
					row.LayoutOrder = idx
					row.BackgroundColor3 = Color3.fromRGB(18, 18, 18)
					row.BorderSizePixel = 0
					cr(6, row)
					local rStk = stk(0.99, Color3.fromRGB(28, 28, 28), row)
					local imgFrame = Instance.new("Frame", row)
					imgFrame.Size = UDim2.new(0, 36, 0, 36)
					imgFrame.Position = UDim2.new(0, 5, 0.5, -18)
					imgFrame.BackgroundColor3 = Color3.fromRGB(10, 10, 10)
					cr(4, imgFrame)
					stk(0.99, Color3.fromRGB(28, 28, 28), imgFrame)
					local packImg = Instance.new("ImageLabel", imgFrame)
					packImg.Size = UDim2.new(1, 0, 1, 0)
					packImg.BackgroundTransparency = 1
					packImg.ScaleType = Enum.ScaleType.Crop
					cr(4, packImg)
					task.spawn(function()
						packImg.Image = resolveImageId(
							PackCustomImages[packName] or "https://i.postimg.cc/mDWcc4JK/defaultanimpack.webp"
						)
					end)
					local nl = lbl(row, packTitle, 11, Enum.Font.GothamBold, C.text)
					nl.Size = UDim2.new(1, -115, 1, 0)
					nl.Position = UDim2.new(0, 48, 0, 0)
					local applyBtn = Instance.new("TextButton", row)
					applyBtn.Size = UDim2.new(0, 55, 0, 22)
					applyBtn.Position = UDim2.new(1, -62, 0.5, -11)
					applyBtn.BackgroundColor3 = Color3.fromRGB(30, 30, 30)
					applyBtn.Text = "Apply"
					applyBtn.TextColor3 = C.text
					applyBtn.Font = Enum.Font.GothamBold
					applyBtn.TextSize = 10
					cr(4, applyBtn)
					stk(0.99, Color3.fromRGB(45, 45, 45), applyBtn)
					applyBtn.MouseEnter:Connect(function()
						applyBtn.BackgroundColor3 = Color3.fromRGB(45, 45, 45)
					end)
					applyBtn.MouseLeave:Connect(function()
						applyBtn.BackgroundColor3 = Color3.fromRGB(30, 30, 30)
					end)
					applyBtn.MouseButton1Click:Connect(function()
						task.spawn(applyOnyxPackage, packName)
						tw(applyBtn, { BackgroundColor3 = C.success, TextColor3 = Color3.fromRGB(0, 0, 0) }):Play()
						task.delay(0.8, function()
							tw(applyBtn, { BackgroundColor3 = Color3.fromRGB(30, 30, 30), TextColor3 = C.text }):Play()
						end)
					end)
				end
			end
			if filter == "" then
				idx = idx + 1
				local divFrame = Instance.new("Frame", p)
				divFrame.Size = UDim2.new(1, 0, 0, 24)
				divFrame.LayoutOrder = idx
				divFrame.BackgroundTransparency = 1
				local divLbl = lbl(
					divFrame,
					"\u{2014} Individual Animations \u{2014}",
					10,
					Enum.Font.GothamBold,
					Color3.fromRGB(120, 120, 120),
					Enum.TextXAlignment.Center
				)
				divLbl.Size = UDim2.new(1, 0, 1, 0)
			end
			local typeOrder = { "Idle", "Walk", "Run", "Jump", "Fall", "Swim", "SwimIdle", "Climb" }
			for _, animType in ipairs(typeOrder) do
				local anims = OriginalAnimations[animType]
				if anims then
					for name, animData in pairs(anims) do
						local combinedName = name .. " (" .. animType .. ")"
						if filter == "" or combinedName:lower():find(filter, 1, true) then
							idx = idx + 1
							local row = Instance.new("Frame", p)
							row.Size = UDim2.new(1, -8, 0, 32)
							row.LayoutOrder = idx
							row.BackgroundColor3 = Color3.fromRGB(18, 18, 18)
							row.BorderSizePixel = 0
							cr(6, row)
							local rStk = stk(0.99, Color3.fromRGB(28, 28, 28), row)
							local nl = lbl(row, combinedName, 11, Enum.Font.GothamMedium, C.text)
							nl.Size = UDim2.new(1, -65, 1, 0)
							nl.Position = UDim2.new(0, 10, 0, 0)
							nl.TextTruncate = Enum.TextTruncate.AtEnd
							local applyBtn = Instance.new("TextButton", row)
							applyBtn.Size = UDim2.new(0, 48, 0, 20)
							applyBtn.Position = UDim2.new(1, -54, 0.5, -10)
							applyBtn.BackgroundColor3 = Color3.fromRGB(30, 30, 30)
							applyBtn.Text = "Apply"
							applyBtn.TextColor3 = C.text
							applyBtn.Font = Enum.Font.GothamBold
							applyBtn.TextSize = 9
							cr(4, applyBtn)
							stk(0.99, Color3.fromRGB(45, 45, 45), applyBtn)
							applyBtn.MouseEnter:Connect(function()
								applyBtn.BackgroundColor3 = Color3.fromRGB(45, 45, 45)
							end)
							applyBtn.MouseLeave:Connect(function()
								applyBtn.BackgroundColor3 = Color3.fromRGB(30, 30, 30)
							end)
							applyBtn.MouseButton1Click:Connect(function()
								task.spawn(setAnimation, animType, animData)
								tw(applyBtn, { BackgroundColor3 = C.success, TextColor3 = Color3.fromRGB(0, 0, 0) }):Play()
								task.delay(0.8, function()
									tw(applyBtn, { BackgroundColor3 = Color3.fromRGB(30, 30, 30), TextColor3 = C.text }):Play()
								end)
							end)
						end
					end
				end
			end
		end
		local packsBuilt = false
		p:GetPropertyChangedSignal("Visible"):Connect(function()
			if p.Visible and not packsBuilt then
				packsBuilt = true
				rebuildPacksList(searchBox.Text)
			end
		end)
		searchBox:GetPropertyChangedSignal("Text"):Connect(function()
			if pages["Packs"].Visible then
				rebuildPacksList(searchBox.Text)
			end
		end)
	end
	do
		local p = Instance.new("Frame", scrollContainer)
		p.Size = UDim2.new(1, 0, 1, 0)
		p.BackgroundTransparency = 1
		p.Visible = false
		pages["Custom"] = p
		local listL = Instance.new("UIListLayout", p)
		listL.Padding = UDim.new(0, 5)
		listL.SortOrder = Enum.SortOrder.LayoutOrder
		for idx, slotName in ipairs({ "Idle", "Walk", "Run", "Jump", "Fall", "Swim", "SwimIdle", "Climb" }) do
			local row = Instance.new("Frame", p)
			row.Size = UDim2.new(1, -4, 0, 32)
			row.LayoutOrder = idx
			row.BackgroundColor3 = Color3.fromRGB(18, 18, 18)
			row.BorderSizePixel = 0
			cr(6, row)
			stk(0.99, Color3.fromRGB(28, 28, 28), row)
			local sLbl = lbl(row, slotName, 11, Enum.Font.GothamBold, C.text)
			sLbl.Size = UDim2.new(0, 55, 1, 0)
			sLbl.Position = UDim2.new(0, 8, 0, 0)
			local idBox = Instance.new("TextBox", row)
			idBox.Size = UDim2.new(1, -118, 0, 22)
			idBox.Position = UDim2.new(0, 65, 0.5, -11)
			idBox.BackgroundColor3 = C.input
			idBox.Text = ""
			idBox.PlaceholderText = slotName == "Idle" and "ID 1, ID 2..." or "Animation ID..."
			idBox.TextColor3 = C.text
			idBox.PlaceholderColor3 = C.sub
			idBox.Font = Enum.Font.Gotham
			idBox.TextSize = 10
			cr(4, idBox)
			stk(0.99, C.border, idBox)
			local ibp = Instance.new("UIPadding", idBox)
			ibp.PaddingLeft = UDim.new(0, 6)
			local setBtn = Instance.new("TextButton", row)
			setBtn.Size = UDim2.new(0, 42, 0, 22)
			setBtn.Position = UDim2.new(1, -48, 0.5, -11)
			setBtn.BackgroundColor3 = Color3.fromRGB(30, 30, 30)
			setBtn.Text = "Set"
			setBtn.TextColor3 = C.text
			setBtn.Font = Enum.Font.GothamBold
			setBtn.TextSize = 10
			cr(4, setBtn)
			stk(0.99, Color3.fromRGB(45, 45, 45), setBtn)
			setBtn.MouseButton1Click:Connect(function()
				local text = idBox.Text
				if slotName == "Idle" then
					local ids = {}
					for num in text:gmatch("%d+") do
						table.insert(ids, num)
					end
					if #ids > 0 then
						task.spawn(setAnimation, "Idle", ids)
					end
				else
					local raw = text:match("%d+")
					if raw then
						task.spawn(setAnimation, slotName, raw)
					end
				end
				tw(setBtn, { BackgroundColor3 = C.success, TextColor3 = Color3.fromRGB(0, 0, 0) }):Play()
				task.delay(0.6, function()
					tw(setBtn, { BackgroundColor3 = Color3.fromRGB(30, 30, 30), TextColor3 = C.text }):Play()
				end)
			end)
		end
		local rRow = Instance.new("Frame", p)
		rRow.Size = UDim2.new(1, -4, 0, 32)
		rRow.BackgroundTransparency = 1
		rRow.LayoutOrder = 99
		local rBtn = Instance.new("TextButton", rRow)
		rBtn.Size = UDim2.new(1, 0, 1, 0)
		rBtn.BackgroundColor3 = Color3.fromRGB(40, 20, 20)
		rBtn.BorderSizePixel = 0
		rBtn.Text = "Reset All Custom Animations"
		rBtn.TextColor3 = Color3.fromRGB(110, 110, 115)
		rBtn.Font = Enum.Font.GothamBold
		rBtn.TextSize = 10
		cr(5, rBtn)
		stk(0.99, Color3.fromRGB(60, 30, 30), rBtn)
		rBtn.MouseButton1Click:Connect(function()
			local char = localPlr.Character
			if not char then
				return
			end
			local Animate = char:FindFirstChild("Animate")
			if not Animate then
				return
			end
			local hum = char:FindFirstChildOfClass("Humanoid")
			if not hum then
				return
			end
			pcall(function()
				freezeChar()
				task.wait(0.05)
				stopAllTracks(hum)
				resetIdle(Animate)
				if Animate:FindFirstChild("walk") then
					Animate.walk.WalkAnim.AnimationId = "http://www.roblox.com/asset/?id=0"
				end
				if Animate:FindFirstChild("run") then
					Animate.run.RunAnim.AnimationId = "http://www.roblox.com/asset/?id=0"
				end
				if Animate:FindFirstChild("jump") then
					Animate.jump.JumpAnim.AnimationId = "http://www.roblox.com/asset/?id=0"
				end
				if Animate:FindFirstChild("fall") then
					Animate.fall.FallAnim.AnimationId = "http://www.roblox.com/asset/?id=0"
				end
				if Animate:FindFirstChild("climb") then
					Animate.climb.ClimbAnim.AnimationId = "http://www.roblox.com/asset/?id=0"
				end
				unfreezeChar()
				Animate.Disabled = true
				task.wait(0.05)
				Animate.Disabled = false
				hum:ChangeState(Enum.HumanoidStateType.Freefall)
			end)
		end)
	end

	local function switchTab(tabName)
		for _, pg in pairs(pages) do
			pg.Visible = false
		end
		if pages[tabName] then
			pages[tabName].Visible = true
		end
		for _, btn in ipairs(tabBtns) do
			local active = btn:GetAttribute("tn") == tabName
			btn.TextColor3 = active and Color3.fromRGB(255, 255, 255) or Color3.fromRGB(140, 140, 140)
			local bar = btn:FindFirstChild("ActiveBar")
			if bar then
				bar.Visible = active
			end
		end
	end
	for _, btn in ipairs(tabBtns) do
		btn.MouseButton1Click:Connect(function()
			switchTab(btn:GetAttribute("tn"))
		end)
	end
	switchTab("Emotes")
	updateTabCounts()
	_slateActualToggleEmoteMenu = function()
		if sg then
			sg.Enabled = not sg.Enabled
		end
	end
	_slateEmoteMenuLoading = false
end

_G.ToggleSlateEmoteMenu = function()
	if not _slateActualToggleEmoteMenu then
		ensureEmoteMenuLoaded()
	end
	if _slateActualToggleEmoteMenu then
		_slateActualToggleEmoteMenu()
	end
end
SlateEspMenu = {}

function SlateEspMenu.espAction()
	local v = _G.siriusValues or siriusValues
	return v and v.actions and v.actions[7]
end

function SlateEspMenu.setEsp(on)
	local act = SlateEspMenu.espAction()
	if not act then
		return
	end
	act.enabled = on and true or false
	pcall(act.callback, act.enabled)
end

function SlateEspMenu.espEnabled()
	local act = SlateEspMenu.espAction()
	return (act and act.enabled) == true
end

function SlateEspMenu.refresh()
	pcall(function()
		if EspRefresh then
			EspRefresh()
		end
	end)
end

