	fillGlow.Parent = volumeFill

	local currentTargetPlayer = nil
	local activeGrabAction = nil
	local grabStateStatus = nil
	local requestedActionParam = nil
	local actionButtonsMap = {}

	local function updateGrabButtonVisuals()
		for actionName, btn in pairs(actionButtonsMap) do
			local grabTypeMap = {
				["Drag"] = "drag",
				["Cute"] = "cute",
				["Left Shoulder"] = "left_shoulder",
				["Right Shoulder"] = "right_shoulder",
				["Head"] = "head"
			}
			local param = grabTypeMap[actionName] or actionName:lower():gsub("%s+", "_")

			if activeGrabAction == actionName then
				btn.Text = "Exit"
				btn.BackgroundColor3 = Color3.fromRGB(180, 40, 40)
			elseif requestedActionParam and requestedActionParam == param then
				btn.Text = "Accept"
				btn.BackgroundColor3 = Color3.fromRGB(40, 140, 40)
			else
				btn.Text = actionName
				btn.BackgroundColor3 = Color3.fromRGB(20, 20, 20)
			end
		end
	end

	local function refreshTargetGrabStatus(targetPlayer)
		if not targetPlayer then return end
		local grabStatusRemote = replicatedStorage:FindFirstChild("GrabStatus")
		if grabStatusRemote and grabStatusRemote:IsA("RemoteFunction") then
			task.spawn(function()
				local ok, r1, r2, r3, r4 = pcall(function()
					return grabStatusRemote:InvokeServer(targetPlayer.UserId)
				end)
				if ok then
					if r1 == true then
						grabStateStatus = "active"
					elseif r2 and type(r2) == "string" then
						grabStateStatus = "requested"
						requestedActionParam = r2:lower():gsub("%s+", "_")
					elseif r3 == true or r4 == true then
						grabStateStatus = "requested"
						requestedActionParam = type(r2) == "string" and r2 or nil
					else
						grabStateStatus = nil
						requestedActionParam = nil
						if activeGrabAction and activeGrabAction ~= "Exit" then
							activeGrabAction = nil
						end
					end
				else
					grabStateStatus = nil
					requestedActionParam = nil
				end
				updateGrabButtonVisuals()
			end)
		end
	end

	-- Helper to trigger Mic Up Remotes safely based on Cobalt HTTP/Remote Logs
	local function triggerMicUpAction(actionName, targetPlayer)
		if not targetPlayer then return end
		local targetUserId = targetPlayer.UserId

		-- If this specific action is active or clicking Exit, send GrabExit
		if activeGrabAction == actionName or actionName == "Exit" or actionName == "exit" then
			local exitRemote = replicatedStorage:FindFirstChild("GrabExit")
			if exitRemote and exitRemote:IsA("RemoteEvent") then
				pcall(function() exitRemote:FireServer() end)
			else
				for _, v in ipairs(replicatedStorage:GetDescendants()) do
					if v:IsA("RemoteEvent") and v.Name:lower():find("grabexit") then
						pcall(function() v:FireServer() end)
					end
				end
			end
			activeGrabAction = nil
			grabStateStatus = nil
			requestedActionParam = nil
			updateGrabButtonVisuals()
			return
		end

		if actionName == "Clone" then
			task.spawn(function()
				local onyx = _G.onyxAPI
				local isReanim = false
				if onyx and onyx.is_reanimated then
					local ok, res = pcall(onyx.is_reanimated)
					isReanim = ok and (res == true)
				end

				if isReanim then
					-- Protect Onyx from disconnect triggers during cloning
					_G.onyx_cloning = true
					if onyx and onyx.flags then
						onyx.flags.cloning = true
					end

					-- Save currently playing animation or emote info
					local savedEmoteId = selectedEmoteId
					local savedEmoteName = (nowPlayingLbl and nowPlayingLbl.Text:gsub("^\u{266a}%s*", "")) or ""
					local savedOnyxUrl, savedOnyxSpeed = nil, 1.0
					if onyx and onyx.is_animation_playing then
						local isPlaying, currentUrl = onyx.is_animation_playing()
						if isPlaying and currentUrl then
							savedOnyxUrl = currentUrl
						end
					end

					-- Capture current characters
					local oldClonedChar = (onyx and onyx.get_clone and onyx.get_clone(localPlayer))
					local oldRealChar = (onyx and onyx.get_real_character and onyx.get_real_character(localPlayer))
						or workspace:FindFirstChild("_slate_real_" .. localPlayer.Name)

					-- Rename old real character so newly spawned models will never collide with it
					if oldRealChar then
						pcall(function()
							oldRealChar.Name = "_slate_old_real_" .. localPlayer.Name
						end)
					end

					-- Match puppet rig to targetPlayer so limbs, joint attachments, and scales match 1:1
					local newClonedChar = nil
					if targetPlayer and targetPlayer.Character and targetPlayer.Character:FindFirstChildOfClass("Humanoid") and onyx and onyx.clone_char then
						local okC, resC = pcall(function()
							return onyx.clone_char(targetPlayer.Character)
						end)
						if okC and resC and resC:FindFirstChildOfClass("Humanoid") then
							newClonedChar = resC
							if oldClonedChar and oldClonedChar:FindFirstChild("HumanoidRootPart") and newClonedChar:FindFirstChild("HumanoidRootPart") then
								newClonedChar:PivotTo(oldClonedChar:GetPivot())
							end
							if onyx.set_model_transparency then
								onyx.set_model_transparency(newClonedChar, 1)
							else
								for _, p in ipairs(newClonedChar:GetDescendants()) do
									if p:IsA("BasePart") then p.Transparency = 1 end
								end
							end
							if onyx.set_cloned_character then
								onyx.set_cloned_character(newClonedChar)
							end
							pcall(function()
								localPlr.Character = newClonedChar
								local cam = workspace.CurrentCamera
								if cam then
									cam.CameraSubject = newClonedChar:FindFirstChildOfClass("Humanoid")
								end
							end)
							if oldClonedChar and oldClonedChar ~= newClonedChar then
								pcall(function() oldClonedChar:Destroy() end)
							end
						end
					end

					local activeClonedChar = newClonedChar or oldClonedChar or (onyx and onyx.get_clone and onyx.get_clone(localPlayer))

					-- Fire the clone remote to Mic Up server
					local cloneRemote = replicatedStorage:FindFirstChild("event_clone_avatar")
					if cloneRemote and cloneRemote:IsA("RemoteEvent") then
						pcall(function() cloneRemote:FireServer(targetUserId) end)
					else
						for _, v in ipairs(replicatedStorage:GetDescendants()) do
							if v:IsA("RemoteEvent") and v.Name:lower():find("clone") then
								pcall(function() v:FireServer(targetUserId) end)
							end
						end
					end

					-- Wait/poll for the server to spawn the new character or update appearance
					local activeReal = nil
					local startWait = os.clock()
					while (os.clock() - startWait) < 0.8 do
						if localPlayer.Character and localPlayer.Character ~= activeClonedChar and localPlayer.Character ~= oldRealChar and localPlayer.Character:FindFirstChildOfClass("Humanoid") then
							activeReal = localPlayer.Character
							break
						end
						for _, m in ipairs(workspace:GetChildren()) do
							if m:IsA("Model") and m ~= activeClonedChar and m ~= oldRealChar and m.Name == localPlayer.Name and m:FindFirstChildOfClass("Humanoid") then
								activeReal = m
								break
							end
						end
						if activeReal then break end
						task.wait(0.04)
					end

					if not activeReal then
						activeReal = oldRealChar or workspace:FindFirstChild("_slate_real_" .. localPlayer.Name)
					end

					if activeReal then
						if onyx and onyx.set_real_character then
							onyx.set_real_character(activeReal)
						elseif onyx and onyx.real_chars then
							onyx.real_chars[localPlayer] = activeReal
						end
						pcall(function()
							activeReal.Name = "_slate_real_" .. localPlayer.Name
						end)
						if oldRealChar and oldRealChar ~= activeReal then
							pcall(function() oldRealChar:Destroy() end)
						end
					end

					-- Ensure activeClonedChar is 100% invisible, unanchored, and active
					if activeClonedChar then
						if onyx and onyx.set_model_transparency then
							onyx.set_model_transparency(activeClonedChar, 1)
						else
							for _, p in ipairs(activeClonedChar:GetDescendants()) do
								if p:IsA("BasePart") then p.Transparency = 1 end
							end
						end
						local cHum = activeClonedChar:FindFirstChildOfClass("Humanoid")
						if cHum then
							cHum.PlatformStand = false
							cHum:ChangeState(Enum.HumanoidStateType.Running)
							pcall(function()
								local cam = workspace.CurrentCamera
								if cam then cam.CameraSubject = cHum end
							end)
						end
						for _, p in ipairs(activeClonedChar:GetDescendants()) do
							if p:IsA("BasePart") and p.Anchored then p.Anchored = false end
						end
						pcall(function()
							localPlr.Character = activeClonedChar
						end)
					end

					-- Ensure activeReal is visible, transparent HRP, and ragdolled
					if activeReal then
						if onyx and onyx.set_model_transparency then
							onyx.set_model_transparency(activeReal, 0)
						else
							for _, p in ipairs(activeReal:GetDescendants()) do
								if p:IsA("BasePart") then p.Transparency = 0 end
							end
						end
						local rHrp = activeReal:FindFirstChild("HumanoidRootPart")
						if rHrp then rHrp.Transparency = 1 end

						local ragRemote = replicatedStorage:FindFirstChild("event_rag")
						if ragRemote and ragRemote:IsA("RemoteEvent") then
							pcall(function() ragRemote:FireServer("Ball") end)
						end

						local rHum = activeReal:FindFirstChildOfClass("Humanoid")
						if rHum then
							local rAnim = rHum:FindFirstChildOfClass("Animator")
							if rAnim then
								for _, track in ipairs(rAnim:GetPlayingAnimationTracks()) do
									pcall(function() track:Stop(0) end)
								end
							end
							for _, track in ipairs(rHum:GetPlayingAnimationTracks()) do
								pcall(function() track:Stop(0) end)
							end
						end
						local rAnimate = activeReal:FindFirstChild("Animate")
						if rAnimate then
							pcall(function() rAnimate.Disabled = true end)
						end
					end

					-- Rebuild Heartbeat sync table with the new character
					if onyx and onyx.mark_sync_dirty then
						onyx.mark_sync_dirty()
					end

					-- Release cloning lock
					_G.onyx_cloning = false
					if onyx and onyx.flags then
						onyx.flags.cloning = false
					end

					-- Resume animations immediately
					task.spawn(function()
						task.wait(0.08)
						if savedOnyxUrl and onyx and onyx.play_animation then
							onyx.play_animation(savedOnyxUrl, savedOnyxSpeed or 1.0)
						elseif savedEmoteId and type(playEmote) == "function" then
							local curId = selectedEmoteId or savedEmoteId
							local curName = (savedEmoteName and savedEmoteName ~= "" and savedEmoteName)
								or (nowPlayingLbl and nowPlayingLbl.Text:gsub("^\u{266a}%s*", ""))
								or ""
							selectedEmoteId = nil
							playEmote(curId, curName)
						end
					end)
				else
					-- Normal avatar clone
					local cloneRemote = replicatedStorage:FindFirstChild("event_clone_avatar")
					if cloneRemote and cloneRemote:IsA("RemoteEvent") then
						pcall(function() cloneRemote:FireServer(targetUserId) end)
					else
						for _, v in ipairs(replicatedStorage:GetDescendants()) do
							if v:IsA("RemoteEvent") and v.Name:lower():find("clone") then
								pcall(function() v:FireServer(targetUserId) end)
							end
						end
					end
					task.wait(0.5)
					local char = localPlayer.Character
					if char then
						local hum = char:FindFirstChildOfClass("Humanoid")
						if hum then hum.PlatformStand = false end
					end
				end
			end)
		else
			-- Exact parameter format for Mic Up GrabRequest:
			-- Argument 1: targetUserId (number)
			-- Argument 2: grabParam (string, e.g. "cute", "drag", "left_shoulder", "right_shoulder", "head")
			local grabRemote = replicatedStorage:FindFirstChild("GrabRequest")
			local grabTypeMap = {
				["Drag"] = "drag",
				["Cute"] = "cute",
				["Left Shoulder"] = "left_shoulder",
				["Right Shoulder"] = "right_shoulder",
				["Head"] = "head"
			}
			local grabParam = grabTypeMap[actionName] or actionName:lower():gsub("%s+", "_")

			if grabRemote and grabRemote:IsA("RemoteEvent") then
				pcall(function() grabRemote:FireServer(targetUserId, grabParam) end)
			else
				for _, v in ipairs(replicatedStorage:GetDescendants()) do
					if v:IsA("RemoteEvent") and (v.Name == "GrabRequest" or v.Name:lower():find("grab")) then
						pcall(function() v:FireServer(targetUserId, grabParam) end)
					end
				end
			end
			activeGrabAction = actionName
			updateGrabButtonVisuals()
		end

		refreshTargetGrabStatus(targetPlayer)
	end

	-- Option buttons (Original Single-Column Stack List Design with UIListLayout & ScrollingFrame)
	local buttonStackFrame = Instance.new("ScrollingFrame")
	buttonStackFrame.Name = "ButtonStackFrame"
	buttonStackFrame.Size = UDim2.new(0, 194, 0, 218)
	buttonStackFrame.Position = UDim2.new(0.43794, 0, 0.20701, 0)
	buttonStackFrame.BackgroundTransparency = 1
	buttonStackFrame.BorderSizePixel = 0
	buttonStackFrame.ScrollBarThickness = 2
	buttonStackFrame.ScrollBarImageColor3 = Color3.fromRGB(80, 80, 80)
	buttonStackFrame.CanvasSize = UDim2.new(0, 0, 0, 0)
	buttonStackFrame.AutomaticCanvasSize = Enum.AutomaticSize.Y
	buttonStackFrame.Parent = mainFrame

	local stackList = Instance.new("UIListLayout")
	stackList.SortOrder = Enum.SortOrder.LayoutOrder
	stackList.Padding = UDim.new(0, 6)
	stackList.Parent = buttonStackFrame

	local stackPadding = Instance.new("UIPadding")
	stackPadding.PaddingTop = UDim.new(0, 2)
	stackPadding.PaddingBottom = UDim.new(0, 2)
	stackPadding.PaddingLeft = UDim.new(0, 2)
	stackPadding.PaddingRight = UDim.new(0, 4)
	stackPadding.Parent = buttonStackFrame

	local buttonNames = { "Cute", "Drag", "Left Shoulder", "Right Shoulder", "Head", "Clone" }

	for idx, bName in ipairs(buttonNames) do
		local btn = Instance.new("TextButton")
		btn.Name = bName .. "Button"
		btn.Size = UDim2.new(1, 0, 0, 36)
		btn.BackgroundColor3 = Color3.fromRGB(13, 13, 13)
		btn.BorderSizePixel = 0
		btn.Text = bName
		btn.TextColor3 = Color3.fromRGB(255, 255, 255)
		btn.TextSize = 13
		btn.LayoutOrder = idx
		btn.FontFace = Font.new("rbxassetid://16658221428", Enum.FontWeight.SemiBold, Enum.FontStyle.Normal)
		btn.Parent = buttonStackFrame

		local btnCorner = Instance.new("UICorner")
		btnCorner.CornerRadius = UDim.new(0, 8)
		btnCorner.Parent = btn

		actionButtonsMap[bName] = btn

		btn.MouseButton1Click:Connect(function()
			if currentTargetPlayer then
				triggerMicUpAction(bName, currentTargetPlayer)
			end
		end)
	end
	local isVolumeDragging = false
	local currentVolume = 1.0

	local function updateVolume(inputPos)
		local trackAbsPos = volumeTrack.AbsolutePosition
		local trackAbsSize = volumeTrack.AbsoluteSize
		if trackAbsSize.X <= 0 then return end

		local relX = math.clamp((inputPos.X - trackAbsPos.X) / trackAbsSize.X, 0, 1)
		currentVolume = relX

		tweenService:Create(volumeFill, TweenInfo.new(0.08, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
			Size = UDim2.new(relX, 0, 1, 0)
		}):Play()

		if currentTargetPlayer then
			local uid = currentTargetPlayer.UserId
			-- 1. VoiceChatInternal mute/unmute control
			pcall(function()
				local vci = game:GetService("VoiceChatInternal")
				if vci then
					if currentVolume <= 0.05 then
						vci:SubscribePause(uid, true)
					else
						vci:SubscribePause(uid, false)
					end
				end
			end)

			-- 2. VoiceChatService player volume
			pcall(function()
				local vcs = game:GetService("VoiceChatService")
				if vcs and vcs.SetPlayerVolume then
					vcs:SetPlayerVolume(currentTargetPlayer, currentVolume)
				end
			end)

			-- 3. Adjust target player's AudioStream / Sound / AudioDeviceOutput instances
			pcall(function()
				local targetChar = currentTargetPlayer.Character
				if targetChar then
					for _, desc in ipairs(targetChar:GetDescendants()) do
						if desc:IsA("Sound") or desc:IsA("AudioPlayer") or desc:IsA("AudioDeviceOutput") then
							pcall(function() desc.Volume = currentVolume end)
						end
					end
				end
			end)
		end
	end

	local function onSliderInputBegan(inp)
		if inp.UserInputType == Enum.UserInputType.MouseButton1 or inp.UserInputType == Enum.UserInputType.Touch then
			isVolumeDragging = true
			updateVolume(inp.Position)
		end
	end

	volumeFrame.InputBegan:Connect(onSliderInputBegan)
	volumeTrack.InputBegan:Connect(onSliderInputBegan)
	volumeFill.InputBegan:Connect(onSliderInputBegan)

	userInputService.InputChanged:Connect(function(inp)
		if isVolumeDragging and (inp.UserInputType == Enum.UserInputType.MouseMovement or inp.UserInputType == Enum.UserInputType.Touch) then
			updateVolume(inp.Position)
		end
	end)

	userInputService.InputEnded:Connect(function(inp)
		if inp.UserInputType == Enum.UserInputType.MouseButton1 or inp.UserInputType == Enum.UserInputType.Touch then
			isVolumeDragging = false
		end
	end)

	-- Check if click is inside volume slider bounds
	local function isInsideVolumeSlider(mousePos)
		local pos = volumeFrame.AbsolutePosition
		local sz = volumeFrame.AbsoluteSize
		return (mousePos.X >= pos.X and mousePos.X <= pos.X + sz.X)
			and (mousePos.Y >= pos.Y and mousePos.Y <= pos.Y + sz.Y)
	end

	-- Check if the Reanim window/GUI is currently open
	local function isReanimWindowOpen()
		local gui = _G.AKReanimGUIInstance
		if gui and gui.Parent and gui.Enabled then
			return true
		end
		return false
	end

	-- Raycast & Mouse Click Listener
	userInputService.InputBegan:Connect(function(input, gameProcessed)
		if input.UserInputType ~= Enum.UserInputType.MouseButton1 and input.UserInputType ~= Enum.UserInputType.Touch then
			return
		end

		-- If clicking inside the active UI frame, handle volume or prevent click-through
		if mainFrame.Visible then
			local mousePos = userInputService:GetMouseLocation()
			local frameAbsPos = mainFrame.AbsolutePosition
			local frameAbsSize = mainFrame.AbsoluteSize
			local inFrame = (mousePos.X >= frameAbsPos.X and mousePos.X <= frameAbsPos.X + frameAbsSize.X)
				and (mousePos.Y >= frameAbsPos.Y and mousePos.Y <= frameAbsPos.Y + frameAbsSize.Y)
			
			if isInsideVolumeSlider(mousePos) then
				isVolumeDragging = true
				updateVolume(input.Position)
				return
			end

			if inFrame or gameProcessed then
				return
			else
				mainFrame.Visible = false
				return
			end
		end

		if gameProcessed then
			return
		end

		-- ONLY open if reanim window is open
		if not isReanimWindowOpen() then
			return
		end

		local mouse = localPlayer:GetMouse()
		local clickedPlayer = nil

		-- Only match if directly clicking a player's character model part
		if mouse and mouse.Target then
			local hitModel = mouse.Target:FindFirstAncestorOfClass("Model")
			if hitModel then
				clickedPlayer = players:GetPlayerFromCharacter(hitModel)
			end
		end

		if clickedPlayer and clickedPlayer ~= localPlayer then
			currentTargetPlayer = clickedPlayer
			nameLabel.Text = clickedPlayer.DisplayName or clickedPlayer.Name
			
			-- Render target player character in 3D ViewportFrame with thumbnail fallback
			task.spawn(function()
				-- Clear old viewport children
				for _, v in ipairs(charViewport:GetChildren()) do
					if v:IsA("Model") or v:IsA("Accoutrement") or v:IsA("Part") then
						v:Destroy()
					end
				end

				local targetChar = clickedPlayer.Character
				local renderedModel = nil

				if targetChar then
					targetChar.Archivable = true
					local okClone, clonedModel = pcall(function() return targetChar:Clone() end)
					if okClone and clonedModel then
						renderedModel = clonedModel
					end
				end

				if renderedModel then
					renderedModel.Parent = charViewport

					local rootPart = renderedModel:FindFirstChild("HumanoidRootPart") or renderedModel:FindFirstChild("Head") or renderedModel.PrimaryPart
					if rootPart then
						local cf, size = renderedModel:GetBoundingBox()
						local maxDim = math.max(size.X, size.Y, size.Z)
						local dist = maxDim * 1.5

						-- Position camera facing the front of the character (rootPart.CFrame.LookVector * dist)
						local centerPos = cf.Position
						local camPos = centerPos + (rootPart.CFrame.LookVector * dist) + Vector3.new(0, 0.4, 0)
						viewportCamera.CFrame = CFrame.new(camPos, centerPos + Vector3.new(0, 0.1, 0))
						viewportCamera.FieldOfView = 48
					end

					charViewport.Visible = true
					avatarImage.Visible = false
				else
					charViewport.Visible = false
					avatarImage.Visible = true

					pcall(function()
						local img = players:GetUserThumbnailAsync(
							clickedPlayer.UserId,
							Enum.ThumbnailType.AvatarBust,
							Enum.ThumbnailSize.Size420x420
						)
						if img then avatarImage.Image = img end
					end)
				end
			end)

			mainFrame.Visible = true
			return
		end

		-- If clicking elsewhere on screen (and not clicking the UI frame itself), hide frame
		if mainFrame.Visible then
			local mousePos = userInputService:GetMouseLocation()
			local frameAbsPos = mainFrame.AbsolutePosition
			local frameAbsSize = mainFrame.AbsoluteSize
			local inFrame = (mousePos.X >= frameAbsPos.X and mousePos.X <= frameAbsPos.X + frameAbsSize.X)
				and (mousePos.Y >= frameAbsPos.Y and mousePos.Y <= frameAbsPos.Y + frameAbsSize.Y)
			
			if not inFrame then
				mainFrame.Visible = false
			end
		end
	end)
end)


function SlateEspMenu.toggle()
	local UI = SlateEspMenu.build()
	if not UI then
		if queueNotification then
			queueNotification("ESP", "The ESP menu is still loading.")
		end
		return
	end
	UI.ToggleMenu()
end
_G.SlateToggleEspMenu = SlateEspMenu.toggle
_G._slateFullyLoaded = true
print(string.format("main script %.4fs", os.clock() - _slateLoadStart))
task.spawn(function()
	local waitStart = os.clock()
	while not (Slate._slateClientDone and Slate._slateReanimDone) and os.clock() - waitStart < 30 do
		task.wait()
	end
	print(string.format("everything loaded in %.4fs", os.clock() - _slateLoadStart))
end)
